/// Classifies one raw drive error word and tracks repeated failures.
///
/// # Original
/// - Ghidra: `FUN_801cb320` at `0x801CB320` (244 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801cb320_FUN_801cb320.c`
/// - Called by [`fn_801cb4f0`] with the word from `0x801D36D0`.
///
/// # Arguments
/// * `raw` - drive error/status word.
///
/// # Returns
/// `0` for ignorable/known status words, `1` for a known repeat, `2` for a
/// retryable/new error and `3` for a fatal error.
///
/// # Side effects
/// Updates [`SDA_DVD_LAST_ERROR`] and increments [`SDA_DVD_ERROR_COUNT`]. The
/// first branch also stores `0x20400` and returns success.
///
/// # Safety
/// The SDA globals and the current state object must be readable.
///
/// # Confidence
/// medium - control flow and stores are exact; the status meanings are inferred
/// from the numeric values.
pub unsafe fn dvd_classify_error_801cb320(raw: u32) -> u32 {
    if raw == 0x0002_0400 {
        platform::write_u32(SDA_DVD_LAST_ERROR, 0x0002_0400);
        return 1;
    }

    let code = raw & 0x00FF_FFFF;
    if code == 0x0006_2800
        || code == 0x0002_3A00
        || code == 0x0005_3000
        || code == 0x000B_5A01
    {
        return 0;
    }

    if code == 0x0005_2000 {
        let state = platform::read_u32(SDA_DVD_STATE) as usize;
        if platform::read_i32(state + 8) == 0x25
            || platform::read_u32(SDA_DVD_CALLBACK) == DVD_KNOWN_CALLBACK
        {
            return 0;
        }
    }

    let count = platform::read_u32(SDA_DVD_ERROR_COUNT).wrapping_add(1);
    platform::write_u32(SDA_DVD_ERROR_COUNT, count);
    if count == 2 {
        if code == platform::read_u32(SDA_DVD_LAST_ERROR) {
            platform::write_u32(SDA_DVD_LAST_ERROR, code);
            return 1;
        }
        platform::write_u32(SDA_DVD_LAST_ERROR, code);
        return 2;
    }

    platform::write_u32(SDA_DVD_LAST_ERROR, code);
    let state = platform::read_u32(SDA_DVD_STATE) as usize;
    if code != 0x0003_1100 && platform::read_i32(state + 8) != 5 {
        return 3;
    }
    2
}

