/// # Confidence
/// medium - the ioctl argument order is inferred from the eight observed
/// arguments; every store is exact.
pub unsafe fn dvd_low_read_fst_801d2f20(
    dst: u32,
    len: u32,
    offset: u32,
    callback: u32,
) -> u32 {
    if (dst & 0x1F) != 0 {
        platform::call1(DVD_LOW_REPORT, MSG_DVD_LOW_READ_ALIGN);
        return 0;
    }

    let context = platform::read_u32(SDA_DVD_CONTEXT_INDEX);
    platform::write_u8(SDA_DVD_CONTEXT_BUSY, 1);
    // observed: `0x801d2f20` passes the context index with the error message.
    dvd_low_claim_context(context, callback, true);
    platform::write_u32(SDA_DVD_LAST_READ_SIZE, len);

    let mut command = platform::read_u32(SDA_DVD_COMMAND_INDEX).wrapping_add(1);
    if command > DVD_LOW_RING_LEN - 1 {
        command = 0;
    }
    platform::write_u32(SDA_DVD_COMMAND_INDEX, command);

    let base = platform::read_u32(SDA_DVD_COMMAND_BUFFER) as usize;
    let slot = base + command as usize * DVD_LOW_COMMAND_STRIDE;
    platform::write_u8(slot, 0x71);
    platform::write_u32(slot + 4, len);
    platform::write_u32(slot + 8, offset);

    let result = dvd_call8(
        DVD_IOS_IOCTL_ASYNC,
        platform::read_u32(SDA_DVD_IOS_FD),
        0x71,
        slot as u32,
        DVD_LOW_COMMAND_STRIDE as u32,
        dst,
        len,
        DVD_LOW_COMPLETION,
        (DVD_LOW_CONTEXT + context as usize * DVD_LOW_CONTEXT_STRIDE) as u32,
    );

    if result == 0 {
        1
    } else {
        platform::call2(DVD_LOW_REPORT, MSG_DVD_LOW_READ_IOCTL, result);
        platform::write_u8(
            DVD_LOW_CONTEXT + context as usize * DVD_LOW_CONTEXT_STRIDE + 8,
            0,
        );
        0
    }
}

/// Submits the low-level "clear cover interrupt" command (`0x86`).
///
/// # Original
/// - Ghidra: `FUN_801d3700` at `0x801D3700` (360 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801d3700_FUN_801d3700.c`
/// - Called by [`dvd_change_disk_801cae90`] with `0`.
///
/// # Arguments
/// * `callback` - completion callback stored in the ioctl context.
///
/// # Returns
/// `true` when the ioctl was queued, `false` on failure or busy context.
///
/// # Side effects
/// Advances the command ring, writes command byte `0x86`, claims a context,
/// and submits `IOS_IoctlAsync(fd, 0x86, cmd, 0x20, 0, 0, 0x801D1060, ctx)`.
///
/// # Safety
/// The low-level context ring must be initialised; the callback must be
/// callable.
///
/// # Confidence
/// medium - body exact; callback and ioctl roles are inferred from the command
/// number and surrounding reset path.
pub unsafe fn dvd_low_clear_cover_interrupt_801d3700(callback: u32) -> bool {
    let mut command = platform::read_u32(SDA_DVD_COMMAND_INDEX).wrapping_add(1);
    if command > DVD_LOW_RING_LEN - 1 {
        command = 0;
    }
    platform::write_u32(SDA_DVD_COMMAND_INDEX, command);

    let base = platform::read_u32(SDA_DVD_COMMAND_BUFFER) as usize;
    let slot = base + command as usize * DVD_LOW_COMMAND_STRIDE;
    platform::write_u8(slot, 0x86);

    let context = platform::read_u32(SDA_DVD_CONTEXT_INDEX);
    platform::write_u8(SDA_DVD_CONTEXT_BUSY, 1);
    // observed: `0x801d3700` reports the message without the index argument.
    dvd_low_claim_context(context, callback, false);

    let record = DVD_LOW_CONTEXT + context as usize * DVD_LOW_CONTEXT_STRIDE;
    let result = dvd_call8(
        DVD_IOS_IOCTL_ASYNC,
        platform::read_u32(SDA_DVD_IOS_FD),
        0x86,
        slot as u32,
        DVD_LOW_COMMAND_STRIDE as u32,
        0,
        0,
        DVD_LOW_COMPLETION,
        record as u32,
    );

    if result != 0 {
        platform::call2(DVD_LOW_REPORT, MSG_DVD_LOW_CLEAR_COVER, result);
        platform::write_u8(record + 8, 0);
    }
    result == 0
}

// ---------------------------------------------------------------------------
// Third pass: completion callbacks, descriptor wait, state dispatch, ioctl
// command builders
// ---------------------------------------------------------------------------
//
// Appended from `0x801CC240`-`0x801D30D0`. This is the other half of the
// low-level layer above: the callbacks the transfer queue and the four-context
// IOS ring invoke, the descriptor wait/advance step, the state-machine
// dispatcher, and the remaining drive command builders. Ghidra models the
// `__savegprlr_*` helpers as calls that "return" registers; those are treated
// as prologue noise exactly as in the second pass.

// --- r13-relative globals (third pass) ------------------------------------

/// `r13-0x4CDC`: kind word of the command block currently being executed.
const SDA_DVD_4CDC: usize = SDA_BASE - 0x4CDC;
/// `r13-0x4D10`: state object installed for the read-id error path.
const SDA_DVD_4D10: usize = SDA_BASE - 0x4D10;
/// `r13-0x4D34`: non-zero asks the state machine to stop instead of retrying.
const SDA_DVD_4D34: usize = SDA_BASE - 0x4D34;
/// `r13-0x4D40`: set when a queued descriptor must be retried.
const SDA_DVD_4D40: usize = SDA_BASE - 0x4D40;
/// `r13-0x4CE4`: event id forwarded to `0x801D06A0` with the default error
/// callback.
const SDA_DVD_4CE4: usize = SDA_BASE - 0x4CE4;
/// `r13-0x4CA0`: previous raw error word for the low-level classifier.
const SDA_DVD_4CA0: usize = SDA_BASE - 0x4CA0;
/// `r13-0x4CA4`: repeat counter for the low-level classifier.
const SDA_DVD_4CA4: usize = SDA_BASE - 0x4CA4;
/// `r13-0x4C97`: byte set while an IOS transaction callback is running.
const SDA_DVD_4C97: usize = SDA_BASE - 0x4C97;
/// `r13-0x4C78`: pending drive-reset byte consumed by `0x801D1060`.
const SDA_DVD_4C78: usize = SDA_BASE - 0x4C78;

// --- absolute globals (third pass) ----------------------------------------

/// `0x803957E0`: state object selected by the read-id completion path.
const DVD_STATE_READ_ID: u32 = 0x8039_57E0;
/// `0x80395800`: 0x20-byte destination of the unencrypted read-id command.
const DVD_READ_ID_BUFFER: usize = 0x8039_5800;
/// `0x80395700`: 0x20-byte destination of the low-level FST read.
const DVD_FST_BUFFER: usize = 0x8039_5700;
/// `0x80395C60`: 0x20-byte input block shared by the error/reset commands.
const DVD_LOW_INPUT_BLOCK: usize = 0x8039_5C60;
/// `0x80395C64`: word copied out of the cover-register block.
const DVD_COVER_STATUS_WORD: usize = 0x8039_5C64;
/// `0x80395C80`: 0x20-byte cover-register block filled by the drive.
const DVD_COVER_REGS: usize = 0x8039_5C80;

// --- external call targets (third pass) -----------------------------------

/// `0x801CFBC0`: non-zero when the low-level queue holds a pending transfer.
const DVD_QUEUE_HAS_WORK: usize = 0x801C_FBC0;
/// `0x801CFB20`: pops the next transfer and returns its state object.
const DVD_QUEUE_POP: usize = 0x801C_FB20;
/// `0x801CDD30`: advances one command block through the low-level state
/// machine.
const DVD_STATE_ADVANCE: usize = 0x801C_DD30;
/// `0x801CFC90`: cancels one descriptor's queued command.
const DVD_CANCEL_DESCRIPTOR: usize = 0x801C_FC90;
/// `0x801D2130`: unencrypted-read command builder (`0x8D`).
const DVD_LOW_UNENCRYPTED_READ: usize = 0x801D_2130;
/// `0x801AB640`: cancels an armed OS alarm.
const DVD_ALARM_CANCEL: usize = 0x801A_B640;

/// `0x801CC3E0`: completion of the 0x20-byte unencrypted read-id command.
const DVD_ID_READ_CALLBACK: u32 = 0x801C_C3E0;
/// `0x801CCD30`: completion of the low-level FST read.
const DVD_FST_LOW_CALLBACK: u32 = 0x801C_CD30;
/// `0x801CD1F0`: timer callback installed by [`fn_801cced0`].
const DVD_TIMER_CALLBACK: u32 = 0x801C_D1F0;

// --- diagnostics (third pass) ---------------------------------------------

/// `"__doTransactionCallback(): Error: ..."` at `0x803424D0`.
const MSG_DVD_TRANSACTION_CALLBACK: u32 = 0x8034_24D0;
/// `"__DVDLowUnencryptedRead(): IOS_IoctlAsync..."` at `0x80342B78`.
const MSG_DVD_LOW_UNENCRYPTED_READ: u32 = 0x8034_2B78;
/// `"__DVDLowStopMotor(): IOS_IoctlAsync..."` at `0x80342BB8`.
const MSG_DVD_LOW_STOP_MOTOR: u32 = 0x8034_2BB8;
/// `"__DVDLowInquiry(): IOS_IoctlAsync..."` at `0x80342C38`.
const MSG_DVD_LOW_INQUIRY: u32 = 0x8034_2C38;
/// `"__DVDLowRequestError(): IOS_IoctlAsync..."` at `0x80342C70`.
const MSG_DVD_LOW_REQUEST_ERROR: u32 = 0x8034_2C70;
/// `"__DVDLowReset(): IOS_IoctlAsync..."` at `0x80342D30`.
const MSG_DVD_LOW_RESET: u32 = 0x8034_2D30;
/// `"__DVDLowSeek(): IOS_IoctlAsync..."` at `0x803431D0`.
const MSG_DVD_LOW_SEEK: u32 = 0x8034_31D0;

/// Arms the shared delayed-retry alarm exactly once.
///
/// # Original
/// - Inlined three times in `FUN_801cda10` at `0x801CDA10` (reasons 2, 3, 4).
/// - Evidence: `work/ghidra/main-gb/export/801cda10_FUN_801cda10.c`.
///
/// # Side effects
/// Sets [`SDA_DVD_4D3C`], initialises [`DVD_RETRY_ALARM_B`] and arms a periodic
/// alarm whose period is `bus_clock / 4000 * 100`.
///
/// # Safety
/// The alarm object must not already be armed; the tick source must be valid.
///
/// # Confidence
/// high - the guard, period and callback are identical in all three copies.
unsafe fn dvd_arm_retry_alarm() {
    if platform::read_u32(SDA_DVD_4D3C) == 0 && platform::read_u32(SDA_DVD_4D38) == 0 {
        platform::write_u32(SDA_DVD_4D3C, 1);
        platform::call1(DVD_ALARM_INIT, DVD_RETRY_ALARM_B as u32);
        let tick = call0_ret(OS_GET_TICK);
        let period = (platform::read_u32(LOW_MEM_BUS_CLOCK) / 4000).wrapping_mul(100);
        call7(
            DVD_ALARM_SET_PERIODIC,
            DVD_RETRY_ALARM_B as u32,
            DVD_ALARM_TICK_ADJUST,
            0,
            tick,
            0,
            period,
            DVD_DELAYED_RETRY_CALLBACK,
        );
    }
}

/// Advances the rotating command-buffer index and returns the new slot.
///
/// # Original
/// - Inlined in `0x801D2130`, `0x801D22D0`, `0x801D2470`, `0x801D25E0`,
///   `0x801D2760` and `0x801D30D0`.
/// - Evidence: `work/ghidra/main-gb/export/801d2130_FUN_801d2130.c` and the
///   sibling builders.
///
/// # Returns
/// The new index (`0..=3`) and the address of its 0x20-byte command slot.
///
/// # Safety
/// [`SDA_DVD_COMMAND_BUFFER`] must point at four 0x20-byte slots.
///
/// # Confidence
/// high - the wrap and stride are identical in every builder.
unsafe fn dvd_low_next_command_slot() -> (u32, usize) {
    let mut command = platform::read_u32(SDA_DVD_COMMAND_INDEX).wrapping_add(1);
    if command > DVD_LOW_RING_LEN - 1 {
        command = 0;
    }
    platform::write_u32(SDA_DVD_COMMAND_INDEX, command);
    let base = platform::read_u32(SDA_DVD_COMMAND_BUFFER) as usize;
    (
        command,
        base + command as usize * DVD_LOW_COMMAND_STRIDE,
    )
}

/// Completion callback that records the status word and drives the next step of
/// a read-id transfer.
///
/// The body matches [`dvd_read_completion_801cb010`] except for the odd-status
/// branch, which installs the read-id state and submits the unencrypted read of
/// 0x20 bytes at disc offset `0x10008` into `0x80395800`.
///
/// # Original
/// - Ghidra: `FUN_801cc240` at `0x801CC240` (416 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801cc240_FUN_801cc240.c`
///
/// # Arguments
/// * `status` - completion status word from the IOS transaction.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Writes the previous ring record's `+0x0C` field and [`G_DVD_LAST_STATUS`]
/// under the interrupt lock; `0x10`/`0x20` install [`DVD_RETRY_CALLBACK`]; an
/// even word appends a `0x27` event and calls `0x801D25E0`; an odd word resets
/// the error count, installs [`DVD_STATE_READ_ID`], clears the cover interrupt,
/// appends a `0x21` event and starts the unencrypted read.
///
/// # Safety
/// The event ring, state pointer and ioctl ring must be initialised.
///
/// # Confidence
/// medium - body exact; the `0x10008` offset and `0x21` event kind are not
/// identified by a symbol.
pub unsafe fn fn_801cc240(status: u32) {
    let token = disable_interrupts();
    let mut value = status;
    if platform::read_u32(SDA_DVD_QUEUE_INDEX) != 0 {
        let idx = platform::read_u32(SDA_DVD_QUEUE_INDEX);
        platform::write_u32(
            DVD_EVENT_RING + 0x0C + (idx as usize - 1) * 0x14,
            status,
        );
        value = platform::read_u32(G_DVD_LAST_STATUS);
    }
    platform::write_u32(G_DVD_LAST_STATUS, value);
    restore_interrupts(token);

    if status == 0x10 {
        platform::call2(
            DVD_SET_SPECIAL_CALLBACK,
            DVD_EVENT_ID_10,
            DVD_RETRY_CALLBACK,
        );
    } else if status == 0x20 {
        platform::call2(
            DVD_SET_SPECIAL_CALLBACK,
            DVD_EVENT_ID_20,
            DVD_RETRY_CALLBACK,
        );
    } else if status & 1 == 0 {
        fn_801cac60(0x27, 0, 0);
        platform::call1(DVD_RETRY_TRANSFER, DVD_RETRY_CONTINUATION);
    } else {
        platform::write_u32(SDA_DVD_ERROR_COUNT, 0);
        platform::write_u32(SDA_DVD_4D10, DVD_STATE_READ_ID);
        platform::call1(DVD_LOW_CLEAR_COVER, 0);

        let token = disable_interrupts();
        dvd_push_event_locked(0x21, 0x0001_0008, 0x20);
        restore_interrupts(token);

        call4(
            DVD_LOW_UNENCRYPTED_READ,
            DVD_READ_ID_BUFFER as u32,
            0x20,
            0x0001_0008,
            DVD_ID_READ_CALLBACK,
        );
    }
}

