/// Dispatches the current low-level command kind to retry, finish or abort.
///
/// # Original
/// - Ghidra: `FUN_801cced0` at `0x801CCED0` (196 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801cced0_FUN_801cced0.c`
///
/// # Arguments
/// None; the command kind is read from [`SDA_DVD_4CDC`].
///
/// # Returns
/// `()`.
///
/// # Side effects
/// * Sets [`SDA_DVD_4CF0`] at entry; the `1`/`2` kinds keep it set and return
///   when the drive flag is non-zero.
/// * The default path clears the flag, stores `1` in the timer hook and
///   installs [`DVD_TIMER_CALLBACK`].
/// * Kinds `4, 5, 0x0D, 0x0F, 0x21, 0x22, 0x25, 0x29, 0x2A` reinitialise the
///   queue, reset the state object and call its `+0x28` callback with `-4`.
/// * Kinds `0x20, 0x23, 0x24, 0x26` restart the state at step 1.
///
/// # Safety
/// The state object and its callback must be valid.
///
/// # Confidence
/// medium - the switch table and constants are exact; the kind meanings are
/// inferred from the surrounding state machine.
pub unsafe fn fn_801cced0() {
    platform::write_u32(SDA_DVD_4CF0, 1);
    match platform::read_u32(SDA_DVD_4CDC) {
        1 | 2 => {
            if platform::read_u32(SDA_DVD_DRIVE_FLAG) != 0 {
                return;
            }
            // observed: fallthrough into the default arm.
            platform::write_u32(SDA_DVD_4CF0, 0);
            platform::call1(DVD_TIMER_RESET, 1);
            platform::call1(DVD_TIMER_SET_CALLBACK, DVD_TIMER_CALLBACK);
        }
        4 | 5 | 0x0D | 0x0F | 0x21 | 0x22 | 0x25 | 0x29 | 0x2A => {
            platform::call0(DVD_QUEUE_LIST_INIT);
            let state = platform::read_u32(SDA_DVD_STATE) as usize;
            platform::write_u32(SDA_DVD_STATE, DVD_STATE_DEFAULT);
            let callback = platform::read_u32(state + 0x28);
            if callback != 0 {
                platform::call1(callback as usize, 0xFFFF_FFFC);
            }
            platform::call0(DVD_STATE_RESTART);
        }
        0x20 => {
            platform::write_u32(SDA_DVD_4CF0, 0);
            // observed: fallthrough into the 0x23/0x24/0x26 arm.
            let state = platform::read_u32(SDA_DVD_STATE) as usize;
            platform::write_u32(state + 0x0C, 1);
            platform::call1(DVD_STATE_ADVANCE, state as u32);
        }
        0x23 | 0x24 | 0x26 => {
            let state = platform::read_u32(SDA_DVD_STATE) as usize;
            platform::write_u32(state + 0x0C, 1);
            platform::call1(DVD_STATE_ADVANCE, state as u32);
        }
        _ => {
            platform::write_u32(SDA_DVD_4CF0, 0);
            platform::call1(DVD_TIMER_RESET, 1);
            platform::call1(DVD_TIMER_SET_CALLBACK, DVD_TIMER_CALLBACK);
        }
    }
}

/// Pops the next queued transfer and dispatches it through the low-level state
/// machine.
///
/// # Original
