    if count != 2 {
        platform::write_u32(SDA_DVD_4CA0, code);
        return if code == 0x0003_1100 { 2 } else { 3 };
    }
    if code == platform::read_u32(SDA_DVD_4CA0) {
        platform::write_u32(SDA_DVD_4CA0, code);
        return 1;
    }
    platform::write_u32(SDA_DVD_4CA0, code);
