/// Submits the seek command (`0xAB`).
///
/// # Original
/// - Ghidra: `FUN_801d30d0` at `0x801D30D0` (384 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801d30d0_FUN_801d30d0.c`
/// - String: `"__DVDLowSeek(): IOS_IoctlAsync..."`.
///
/// # Arguments
/// * `offset` - seek target written to command `+4`.
/// * `callback` - completion callback for the context.
///
/// # Returns
/// `true` when the ioctl was queued, `false` on failure or a busy context.
///
/// # Side effects
/// Claims a context, writes command byte `0xAB` and `offset`, and submits
/// `IOS_IoctlAsync(fd, 0xAB, cmd, 0x20, 0, 0, 0x801D1060, ctx)`.
///
/// # Safety
/// The ioctl ring must be ready.
///
/// # Confidence
/// high - the command byte and string identify the routine.
pub unsafe fn dvd_low_seek_801d30d0(offset: u32, callback: u32) -> bool {
    let context = platform::read_u32(SDA_DVD_CONTEXT_INDEX);
    platform::write_u8(SDA_DVD_CONTEXT_BUSY, 1);
    dvd_low_claim_context(context, callback, false);

    let (_, slot) = dvd_low_next_command_slot();
    platform::write_u8(slot, 0xAB);
    platform::write_u32(slot + 4, offset);

    let record = DVD_LOW_CONTEXT + context as usize * DVD_LOW_CONTEXT_STRIDE;
    let result = dvd_call8(
        DVD_IOS_IOCTL_ASYNC,
        platform::read_u32(SDA_DVD_IOS_FD),
        0xAB,
        slot as u32,
        DVD_LOW_COMMAND_STRIDE as u32,
        0,
        0,
        DVD_LOW_COMPLETION,
        record as u32,
    );
    if result != 0 {
        platform::call2(DVD_LOW_REPORT, MSG_DVD_LOW_SEEK, result);
        platform::write_u8(record + 8, 0);
    }
    result == 0
}

