    if status == 0x10 {
        platform::call2(
            DVD_SET_SPECIAL_CALLBACK,
            DVD_EVENT_ID_10,
            DVD_RETRY_CALLBACK,
        );
    } else if status == 0x20 {
        platform::call2(
            DVD_SET_SPECIAL_CALLBACK,
            DVD_EVENT_ID_20,
            DVD_RETRY_CALLBACK,
        );
    } else if status & 1 == 0 {
        fn_801cac60(0x27, 0, 0);
        platform::call1(DVD_RETRY_TRANSFER, DVD_COMPLETION_801CBBE0);
    } else {
        let token = disable_interrupts();
        dvd_push_event_locked(0x10, 0, 0);
        restore_interrupts(token);
        platform::call3(DVD_LOW_RETRY, 0, 0, DVD_EVENT_CONTINUATION);
    }
