const DVD_ERROR_LOG_BLOCK: usize = 0x8039_5A40;

/// `0x80395AC0`: second 0x80-byte staging record, used while reading a slot.
const DVD_ERROR_LOG_BLOCK_B: usize = 0x8039_5AC0;

/// `0x80395AD8`: rotating 0..6 slot counter advanced by `0x801CFFE0`.
const DVD_ERROR_LOG_SLOT: usize = 0x8039_5AD8;

/// `0x80395A48`: first word of the five-word error-info block. The following
