/// Returns the sizes of the two no-disc buffers by submitting the `0x92`
/// ioctlv command.
///
/// # Original
/// - Ghidra: `FUN_801d1b10` at `0x801D1B10` (528 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801d1b10_FUN_801d1b10.c`
/// - String: `"DVDLowGetNoDiscBufferSizes"`.
/// - Caller: `0x801CDD30` passes `state+0x10`, `state+0x3A0` and
///   `state+0x4DC0`.
///
/// # Arguments
/// * `offset` - word written to command `+4` (the caller's `state+0x10`).
/// * `num_tmd_bytes` - 32-byte-aligned output buffer for the TMD size.
/// * `certificates` - 32-byte-aligned output buffer for the certificate size.
/// * `callback` - completion stored in the ioctl context.
///
/// # Returns
/// `true` when the ioctl was queued.
///
/// # Side effects
/// Claims a context, advances the command ring, writes command byte `0x92`,
/// fills three shared vectors and submits
/// `IOS_IoctlvAsync(fd, 0x92, 1, 2, vec, 0x801D1060, ctx)`.
///
/// # Safety
/// Both output buffers must be aligned and writable for four bytes.
///
/// # Confidence
/// high - the command byte, three-vector layout and string identify the body.
pub unsafe fn dvd_low_get_no_disc_buffer_sizes_801d1b10(
    offset: u32,
    num_tmd_bytes: u32,
    certificates: u32,
    callback: u32,
) -> bool {
    if num_tmd_bytes == 0 || certificates == 0 {
        platform::call2(
            DVD_LOW_REPORT,
            MSG_DVD_NULL_ARGUMENT,
            MSG_DVD_NO_DISC_BUFFER_SIZES,
        );
        return false;
    }
    if (num_tmd_bytes & 0x1F) != 0 {
        platform::call2(
            DVD_LOW_REPORT,
            MSG_DVD_NUM_TMD_UNALIGNED,
            MSG_DVD_NO_DISC_BUFFER_SIZES,
        );
        return false;
    }
    if (certificates & 0x1F) != 0 {
        platform::call2(
            DVD_LOW_REPORT,
            MSG_DVD_CERTS_UNALIGNED,
            MSG_DVD_NO_DISC_BUFFER_SIZES,
        );
        return false;
    }

    let context = platform::read_u32(SDA_DVD_CONTEXT_INDEX);
    platform::write_u8(SDA_DVD_CONTEXT_BUSY, 1);
    dvd_low_claim_context(context, callback, true);

    let (_, slot) = dvd_low_next_command_slot();
    platform::write_u8(slot, 0x92);
    platform::write_u32(slot + 4, offset);

    dvd_low_set_iov(0, slot as u32, 0x20);
    dvd_low_set_iov(1, num_tmd_bytes, 4);
    dvd_low_set_iov(2, certificates, 4);

    let record = DVD_LOW_CONTEXT + context as usize * DVD_LOW_CONTEXT_STRIDE;
    let result = platform::call7(
        IOS_IOCTLV_ASYNC,
        platform::read_u32(SDA_DVD_IOS_FD),
        0x92,
        1,
        2,
        DVD_LOW_IOVEC as u32,
        DVD_LOW_COMPLETION,
        record as u32,
    );
    if result != 0 {
        platform::call3(
            DVD_LOW_REPORT,
            MSG_DVD_IOCTLV_ASYNC,
            MSG_DVD_NO_DISC_BUFFER_SIZES,
            result,
        );
        platform::write_u8(record + 8, 0);
        false
    } else {
        true
    }
}

