    platform::write_u32(slot + 4, offset);

    dvd_low_set_iov(0, slot as u32, 0x20);
    dvd_low_set_iov(1, tmd_size_ptr, 4);
    dvd_low_set_iov(2, cert_size_ptr, 4);
    dvd_low_set_iov(3, work, 0x2A4);
    dvd_low_set_iov(4, tmd_size_ptr, 4);
    dvd_low_set_iov(5, tmd, platform::read_u32(tmd_size_ptr as usize));
    dvd_low_set_iov(6, cert_size_ptr, 4);
    dvd_low_set_iov(7, cert, platform::read_u32(cert_size_ptr as usize));
