/// Submits the streamed data-read step shared by command kinds `1`, `4` and
/// `0x21` of [`dvd_state_step_801cdd30`].
///
/// # Original
/// - Inlined three times in `FUN_801cdd30` at `0x801CDD30`.
/// - Evidence: `work/ghidra/main-gb/export/801cdd30_FUN_801cdd30.c`.
///
/// # Arguments
/// * `state` - file-info object.
/// * `callback` - completion callback (`0x801CE2E0` in all three copies).
/// * `unencrypted` - selects `0x801D2130` (true) or `0x801D2F20` (false).
///
/// # Side effects
/// Completes the descriptor when the byte count is zero; otherwise clears the
/// cover latch, clamps the transfer to `0x80000` bytes, records one event and
/// submits the read.
///
/// # Safety
/// `state` and its buffer must be valid.
///
/// # Confidence
/// high - the three copies differ only in the final call target.
unsafe fn dvd_state_step_read(state: usize, callback: u32, unencrypted: bool) {
    let total = platform::read_u32(state + 0x14);
    if total == 0 {
        let old = platform::read_u32(SDA_DVD_STATE) as usize;
        platform::write_u32(SDA_DVD_STATE, DVD_STATE_DEFAULT);
        platform::write_u32(old + 0x0C, 0);
        let completion = platform::read_u32(old + 0x28);
        if completion != 0 {
            platform::call1(completion as usize, 0);
        }
        dvd_state_dispatch_801cda10();
        return;
    }

    platform::call1(DVD_LOW_CLEAR_COVER, 0);
    let offset = platform::read_u32(state + 0x20);
    let mut size = total.wrapping_sub(offset);
    if size > 0x8_0000 {
        size = 0x8_0000;
    }
    platform::write_u32(state + 0x1C, size);

    let position = platform::read_u32(state + 0x10).wrapping_add(offset >> 2);
    let token = disable_interrupts();
    dvd_push_event_locked(platform::read_u32(state + 0x08), position, size);
    restore_interrupts(token);

    let dst = platform::read_u32(state + 0x18).wrapping_add(offset);
    if unencrypted {
        dvd_low_unencrypted_read_801d2130(dst, size, position, callback);
    } else {
        dvd_low_read_fst_801d2f20(dst, size, position, callback);
    }
}

/// Handles one completion status for the DVD state machine.
///
/// # Original
/// - Ghidra: `FUN_801ce2e0` at `0x801CE2E0` (2,528 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801ce2e0_FUN_801ce2e0.c`
/// - Installed as the completion callback by [`dvd_state_step_801cdd30`].
///
/// # Arguments
/// * `status` - low-level completion result; `0x10`/`0x20` are special
