    let found = fn_801d3880(HEAP_ROOT, block as u32);
    let list = if found != 0 { found + 0x0C } else { HEAP_ROOT };
    platform::call2(HEAP_CLEAR, list as u32, block as u32);
    platform::call1(HEAP_MUTEX_UNLOCK, HEAP_MUTEX as u32);
