    let mut left = (node as isize - ((platform::read_u16(node + 2) as u32 >> 8 & 0x7F) as isize)) as usize;
    let right_end = (node + platform::read_u32(node + 4) as usize + 0x10) as usize;

    if right == 0 {
        platform::write_u32(list, tail as u32);
    } else {
        platform::write_u32(right + 0x0C, tail as u32);
    }
    if tail == 0 {
        platform::write_u32(list + 4, right as u32);
    } else {
        platform::write_u32(tail + 8, right as u32);
    }

    if left_end.wrapping_sub(left) > 0x13
        && (flag != 0 || (platform::read_u16(list + 0x12) >> 1 & 1) != 0)
    {
        platform::write_u16(left, 0x4652);
        platform::write_u16(left + 2, 0);
        platform::write_u32(left + 4, (left_end - (left + 8)) as u32);
        platform::write_u32(left + 0x0C, 0);
        platform::write_u32(left + 8, right as u32);
        if right == 0 {
            let front = platform::read_u32(list) as usize;
            platform::write_u32(list, left as u32);
            tail = front;
        } else {
            tail = platform::read_u32(right + 0x0C) as usize;
            platform::write_u32(right + 0x0C, left as u32);
        }
        platform::write_u32(left + 0x0C, tail as u32);
        right = left;
        left = left_end;
        if tail == 0 {
            platform::write_u32(list + 4, left as u32);
        } else {
            platform::write_u32(tail + 8, left as u32);
        }
    }

    let user = (base as usize).wrapping_sub(0x10);
    // observed: `puVar9` is the `param_4 + param_3` address for the right
    // subrecord, not `size - 0x10`.
    let mut right_edge = (base as usize).wrapping_add(size as usize);
    if (right_end.wrapping_sub(right_edge) > 0x13)
        && (flag != 1 || (platform::read_u16(list + 0x12) >> 1 & 1) != 0)
    {
        platform::write_u16(right_edge, 0x4652);
        platform::write_u16(right_edge + 2, 0);
        platform::write_u32(right_edge + 4, (right_end - (right_edge + 8)) as u32);
        platform::write_u32(right_edge + 0x0C, 0);
        platform::write_u32(right_edge + 8, right as u32);
        if right == 0 {
            let front = platform::read_u32(list) as usize;
            platform::write_u32(list, right_edge as u32);
            tail = front;
        } else {
            tail = platform::read_u32(right + 0x0C) as usize;
            platform::write_u32(right + 0x0C, right_edge as u32);
        }
        platform::write_u32(right_edge + 0x0C, tail as u32);
        right_edge = right_edge;
        if tail == 0 {
            platform::write_u32(list + 4, right_edge as u32);
        } else {
            platform::write_u32(tail + 8, right_edge as u32);
        }
    }

    if platform::read_u32(list.wrapping_sub(4)) & 1 != 0 {
        platform::call3(MEMSET, left as u32, 0, (right_end - left) as u32);
    }
    platform::write_u16(user, 0x5544);
    // observed: Ghidra truncates both addresses to `short` before the
    // multiply; the `0x7F00` mask keeps only the low 7 bits of the product.
    let len = (((user as u16).wrapping_sub(left as u16) as u32) * 0x100) & 0x7F00 | (flag << 0x0F);
    platform::write_u32((base as usize).wrapping_sub(0x0C), (right_end - base as usize) as u32);
    platform::write_u32((base as usize).wrapping_sub(8), 0);
    platform::write_u32((base as usize).wrapping_sub(4), 0);
    let tag = platform::read_u32(list + 0x10) & 0xFF | len;
    platform::write_u16((base as usize).wrapping_sub(0x0E), tag as u16);
    let inner = platform::read_u32(list + 0x0C);
    platform::write_u32((base as usize).wrapping_sub(8), inner);
    if inner == 0 {
        let prev = platform::read_u32(list + 8) as usize;
        platform::write_u32(list + 8, user as u32);
        tail = prev;
    } else {
        tail = platform::read_u32(inner as usize + 0x0C) as usize;
        platform::write_u32(inner as usize + 0x0C, user as u32);
    }
    platform::write_u32((base as usize).wrapping_sub(4), tail as u32);
    if tail == 0 {
        platform::write_u32(list + 0x0C, user as u32);
    } else {
        platform::write_u32(tail + 8, user as u32);
    }
