                let next = platform::read_u32(prev + 0x18);
                if node == 0 {
                    platform::write_u32(list, next);
                } else {
                    platform::write_u32(node + 0x18, next);
                }
                start = prev;
                if next == 0 {
                    platform::write_u32(list + 4, node as u32);
                } else {
                    platform::write_u32(next as usize + 8, node as u32);
                }
