            if end.wrapping_sub(start as u32) < 0x10 {
                return 0;
            }
            platform::write_u16(start, 0x4652);
            platform::write_u16(start + 2, 0);
            platform::write_u32(start + 8, end.wrapping_sub((start + 8) as u32));
            platform::write_u32(start + 0x18, 0);
            platform::write_u32(start + 0x10, node as u32);
