        platform::write_u32(slot + 4, front as u32);
        platform::write_u32(slot + 8, platform::read_u32(heap + 0x40));
        platform::write_u32(slot + 0x0C, platform::read_u32(heap + 0x44));
        platform::write_u32(heap + 0x44, slot as u32);
