/// Appends one record to a stride list, bumping its count.
///
/// # Original
/// - Ghidra: `FUN_801d55e0` at `0x801D55E0` (112 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801d55e0_FUN_801d55e0.c`
///
/// # Arguments
/// * `this` - list header (`+0` head, `+4` tail, `+8` count, `+10` stride).
/// * `record` - record address to append.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Links `record` (shifted by the `+10` stride) at the tail, or installs
/// it as head and tail when the list is empty; increments the `+8` count.
///
/// # Safety
/// `this` must be live and `record` must be a writable record whose
/// `+0`/`+4` link words are free.
///
/// # Confidence
/// high - the empty/non-empty paths and the count bump are literal.
pub unsafe fn fn_801d55e0(this: usize, record: usize) {
    let stride = platform::read_u16(this + 10) as usize;
    if platform::read_u32(this) == 0 {
        let node = record + stride;
        platform::write_u32(node, 0);
        platform::write_u32(node + 4, 0);
        platform::write_u32(this, record as u32);
        platform::write_u32(this + 4, record as u32);
        let count = platform::read_u16(this + 8);
        platform::write_u16(this + 8, count.wrapping_add(1));
        return;
    }
    let node = record + stride;
    let tail = platform::read_u32(this + 4) as usize;
    platform::write_u32(node, tail as u32);
    platform::write_u32(node + 4, 0);
    platform::write_u32(tail + stride + 4, record as u32);
    platform::write_u32(this + 4, record as u32);
    let count = platform::read_u16(this + 8);
    platform::write_u16(this + 8, count.wrapping_add(1));
}

/// Unlinks one record from a stride list, decrementing its count.
///
/// # Original
/// - Ghidra: `FUN_801d5650` at `0x801D5650` (108 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801d5650_FUN_801d5650.c`
///
/// # Arguments
/// * `this` - list header (`+0` head, `+4` tail, `+8` count, `+10` stride).
/// * `record` - record address to unlink.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Splices `record` out of the list (updating head or tail), zeroes its
/// link words and decrements the `+8` count.
///
/// # Safety
/// `record` must be a member of the list rooted at `this`.
///
/// # Confidence
/// high - the unlink paths and the count decrement are literal.
pub unsafe fn fn_801d5650(this: usize, record: usize) {
    let stride = platform::read_u16(this + 10) as usize;
    let node = record + stride;
    let prev = platform::read_u32(node) as usize;
    if prev == 0 {
        platform::write_u32(this, platform::read_u32(node + 4));
    } else {
        platform::write_u32(prev + stride + 4, platform::read_u32(node + 4));
    }
    let next = platform::read_u32(node + 4) as usize;
    if next == 0 {
        platform::write_u32(this + 4, prev as u32);
    } else {
        platform::write_u32(next + stride, prev as u32);
    }
    platform::write_u32(node, 0);
    platform::write_u32(node + 4, 0);
    let count = platform::read_u16(this + 8);
    platform::write_u16(this + 8, count.wrapping_sub(1));
}

/// Returns the next link of a stride list, or the head when `node` is 0.
///
/// # Original
/// - Ghidra: `FUN_801d56c0` at `0x801D56C0` (32 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801d56c0_FUN_801d56c0.c`
///
/// # Arguments
/// * `this` - list header (`+0` head, `+10` stride).
/// * `node` - current record, or 0 to read the head.
///
/// # Returns
/// `this + 0` when `node == 0`, otherwise the word at `node + stride + 4`.
///
/// # Side effects
/// None.
///
/// # Safety
/// `this` must be live; `node` must be 0 or a stride record of that list.
///
/// # Confidence
/// high - the guard and two loads are literal in the export.
pub unsafe fn fn_801d56c0(this: usize, node: usize) -> usize {
    if node == 0 {
        return platform::read_u32(this) as usize;
    }
    let stride = platform::read_u16(this + 10) as usize;
    platform::read_u32(node + stride + 4) as usize
}

