        platform::write_u32(SDA_DSP_TAIL, task as u32);
        platform::write_u32(SDA_DSP_ACTIVE, task as u32);
        platform::write_u32(task + 0x3C, 0);
        platform::write_u32(task + 0x38, 0);
        return;
