const GX_TOKEN_SHADOW: usize = 0x8039_0200;

/// `0x801C32E0`: refreshes both token blocks from the source registers.
const GX_TOKEN_REFRESH: usize = 0x801C_32E0;
/// `0x801B11B0`: installs an interrupt handler (`irq, handler`).
const GX_IRQ_SET_HANDLER: usize = 0x801B_11B0;
/// `0x801B1590`: enables the interrupt mask bits passed in its argument.
const GX_IRQ_ENABLE: usize = 0x801B_1590;
/// `0x801B4B20`: initialises a thread queue.
const GX_QUEUE_INIT: usize = 0x801B_4B20;
/// `0x801B4B30`: reads the current tick/timebase word.
