/// `strcmp` against each record's three-byte code.
///
/// # Safety
/// The text block at `0x80003800` and the table must be readable.
///
/// # Confidence
/// medium - same shape as [`fn_801dd860`] with a three-byte value and a
/// four-byte stride; key text and id meanings are unknown.
pub unsafe fn fn_801dd940() -> u32 {
    let mut value = [0u8; 0x10];
    if platform::call3(
        SETTINGS_TEXT_LOOKUP,
        SDA_SETTINGS_KEY_3 as u32,
        value.as_mut_ptr() as u32,
        3,
    ) != 0
    {
        let mut entry = SETTINGS_CODE_TABLE_B;
        loop {
            let id = platform::read_u8(entry);
            if id == 0xFF {
                break;
            }
            if platform::call2(STRING_COMPARE, (entry + 1) as u32, value.as_ptr() as u32) == 0 {
                return id as u32;
            }
            // observed: each record is one id byte followed by a three-byte code.
            entry += 4;
        }
    }
    0xFFFF_FFFF
}

/// Swaps bit 6 of the low-memory boot flag byte and returns the old bit.
///
/// # Original
/// - Ghidra: `FUN_801dd9d0` at `0x801DD9D0` (92 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801dd9d0_FUN_801dd9d0.c`
///
/// # Arguments
/// * `enable` - non-zero sets bit 6 (`0x40`), zero leaves it clear.
///
/// # Returns
/// The bit-6 value from before the swap (`0` or `1`).
///
/// # Side effects
/// Clears bit 6 of `0x800030E3` under the interrupt lock and sets it again when
/// `enable` is non-zero; every other bit is preserved.
///
/// # Safety
/// `0x800030E3` must be a writable low-memory byte.
///
/// # Confidence
/// high - the mask, the store, the optional set and the returned shift are all
/// literal.
pub unsafe fn fn_801dd9d0(enable: bool) -> u8 {
    let token = disable_interrupts();
    let old = platform::read_u8(LOW_MEM_BOOT_FLAGS);
    let cleared = old & 0xBF;
    platform::write_u8(LOW_MEM_BOOT_FLAGS, cleared);
    if enable {
        platform::write_u8(LOW_MEM_BOOT_FLAGS, cleared | 0x40);
    }
    restore_interrupts(token);
    (old >> 6) & 1
}

