// ---------------------------------------------------------------------------
// Wave 80: the GX command pipeline, `0x801C2CE0`-`0x801C56C0`.
//
// The two nine-word blocks below are the command-processor (CP) and
// graphics-processor (GP) FIFO control records. Word 0 is the current write
// pointer and word 1 the read pointer, which is what `fn_801c2d70` compares;
// `+0x20` is a control word whose bytes 2/3 are the "busy" markers. The
// `r13 - 0x4DEC` block is the 16-bit mirror the CP block is copied into for
// the hardware.
// ---------------------------------------------------------------------------

/// `0x80390200`: CP FIFO control block (nine words). `// inferred:`
const GX_CP_FIFO_BLOCK: usize = 0x8039_0200;

/// `0x80390224`: GP FIFO control block (nine words). Wave 67 documented the
/// same address as [`GX_TOKEN_BLOCK`] because the draw token is the GP write
/// pointer. `// inferred:`
const GX_GP_FIFO_BLOCK: usize = 0x8039_0224;

/// `r13 - 0x4DF0`: pointer to the GP register window written at `+0xC`,
/// `+0x10` and `+0x14`. `// inferred:`
const SDA_GX_GP_REGS: usize = SDA_BASE - 0x4DF0;

/// `r13 - 0x4DB0`: byte flag meaning "the GP block is being committed".
/// Set by [`fn_801c35c0`]'s consumers and tested by [`fn_801c32e0`].
/// `// inferred:`
const SDA_GX_GP_ACTIVE: usize = SDA_BASE - 0x4DB0;

/// `r13 - 0x4DC0`: word cleared when the GP commit finishes. `// unknown:`
/// the only accesses are the store to zero here and in [`fn_801c35c0`].
const SDA_GX_EXTRA_COUNT: usize = SDA_BASE - 0x4DC0;

/// `0x80340E20`: "CPUFifo:" report format used by [`fn_801c2d70`].
const MSG_GX_CPU_FIFO: usize = 0x8034_0E20;

/// `0x80340E38`: "GP Fifo:" report format used by [`fn_801c2d70`].
const MSG_GX_GP_FIFO: usize = 0x8034_0E38;

/// Copies the low half-word of `value` into the 16-bit CP mirror block.
///
/// # Safety
/// The small-data pointer at [`SDA_GX_STATUS_BLOCK`] must address the block.
#[inline]
unsafe fn gx_mirror_status(value: u32) {
    let block = platform::read_u32(SDA_GX_STATUS_BLOCK) as usize;
    platform::write_u16(block + 2, value as u16);
}

/// Initialises an eight-word FIFO control record.
///
/// # Original
/// - Ghidra: `FUN_801c2ce0` at `0x801C2CE0` (140 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801c2ce0_FUN_801c2ce0.c`
///
/// # Arguments
/// * `record` - address of the eight-word record to fill.
/// * `base` - FIFO start address.
/// * `size` - FIFO length in bytes.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Stores the write limit (`base + size - 4`), the length, the length minus
/// `0x4000`, the half-length rounded down to `0x20`, and - under the
/// `0x801B1140`/`0x801B1180` interrupt lock - both pointers and the fourth
/// word again.
///
/// # Safety
/// `record` must address at least `0x20` writable bytes.
///
/// # Confidence
/// high - every store and the guarded triple are literal in the export.
pub unsafe fn fn_801c2ce0(record: usize, base: u32, size: u32) {
    platform::write_u32(record, base);
    platform::write_u32(record + 4, base.wrapping_add(size).wrapping_sub(4));
    platform::write_u32(record + 8, size);
    platform::write_u32(record + 0x1C, 0);
    platform::write_u32(record + 0xC, size.wrapping_sub(0x4000));
    platform::write_u32(record + 0x10, (size >> 1) & 0x7FFF_FFE0);
    let token = disable_interrupts();
    platform::write_u32(record + 0x14, base);
    platform::write_u32(record + 0x18, base);
    platform::write_u32(record + 0x1C, 0);
    restore_interrupts(token);
}

/// Reports whether the CP and GP FIFO pointers describe a complete transfer.
///
/// # Original
/// - Ghidra: `FUN_801c2d70` at `0x801C2D70` (248 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801c2d70_FUN_801c2d70.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// `1` when both pairs of pointers are equal (nothing outstanding), `0` in
/// every other case.
///
/// # Side effects
/// When both token flags are set and the pointers cross, emits the
/// `0x80340E20`/`0x80340E38` reports through `0x8015F730`.
///
/// # Safety
/// Both FIFO blocks and the `r13` flags must be mapped.
///
/// # Confidence
/// medium - the compares and the two report calls are literal; the CP/GP roles
/// of the two blocks are inferred from word 0 being the write pointer.
pub unsafe fn fn_801c2d70() -> u32 {
    let flag_a = platform::read_u8(SDA_GX_TOKEN_DIRTY_A);
    let flag_b = platform::read_u8(SDA_GX_TOKEN_DIRTY_B);
    if flag_a == 0 || flag_b == 0 {
        return 0;
    }
    let gp0 = platform::read_u32(GX_GP_FIFO_BLOCK);
    let gp1 = platform::read_u32(GX_GP_FIFO_BLOCK + 4);
    let cp0 = platform::read_u32(GX_CP_FIFO_BLOCK);
    let cp1 = platform::read_u32(GX_CP_FIFO_BLOCK + 4);
    let mut equal = 0u8;
    if gp0 == cp0 {
        equal += 1;
    }
    if gp1 == cp1 {
        equal += 1;
    }
    if equal == 2 {
        return 1;
    }
    // observed: the two signed differences are taken cross-wise, GP word 1
    // against CP word 0 and CP word 1 against GP word 0.
    let delta_a = gp1.wrapping_sub(cp0) as i32;
    let delta_b = cp1.wrapping_sub(gp0) as i32;
    if (delta_a > 0 && delta_b > 0) || (delta_a < 0 && delta_b < 0) {
        platform::call1(DVD_LOW_REPORT, MSG_GX_CPU_FIFO as u32);
        platform::call3(DVD_LOW_REPORT, MSG_GX_GP_FIFO as u32, cp0, cp1);
    }
    0
}

/// Refreshes the CP and GP FIFO blocks from the live pointers.
///
/// # Original
/// - Ghidra: `FUN_801c32e0` at `0x801C32E0` (256 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801c32e0_FUN_801c32e0.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Under the interrupt lock, copies the GP limit from the register window into
/// `GP+0x18` and the busy bit into `GP+0x20`; when the second token flag is
/// set, rebuilds `CP+0x14`/`CP+0x1C` from the two mirror half-word pairs; then,
/// depending on [`SDA_GX_GP_ACTIVE`], either recomputes the outstanding byte
/// count or copies the GP limit/state back into the CP block.
///
/// # Safety
/// Both blocks, the register window and the mirror block must be writable.
///
/// # Confidence
/// medium - all stores are literal; the two blocks' roles and the meaning of
/// the two token flags are inferred.
pub unsafe fn fn_801c32e0() {
    let token = disable_interrupts();
    if platform::read_u8(SDA_GX_TOKEN_DIRTY_A) != 0 {
        let regs = platform::read_u32(SDA_GX_GP_REGS) as usize;
        let limit = platform::read_u32(regs + 0x14);
        platform::write_u8(GX_GP_FIFO_BLOCK + 0x20, ((limit >> 29) & 1) as u8);
        platform::write_u32(
            GX_GP_FIFO_BLOCK + 0x18,
            (limit & 0x1FFF_FFE0).wrapping_add(0x8000_0000),
        );
    }
    if platform::read_u8(SDA_GX_TOKEN_DIRTY_B) != 0 {
        let block = platform::read_u32(SDA_GX_STATUS_BLOCK) as usize;
        let low = ((platform::read_u16(block + 0x3A) as u32) << 16)
            | platform::read_u16(block + 0x38) as u32;
        platform::write_u32(GX_CP_FIFO_BLOCK + 0x14, low.wrapping_sub(0x8000_0000));
        let high = ((platform::read_u16(block + 0x32) as u32) << 16)
            | platform::read_u16(block + 0x30) as u32;
        platform::write_u32(GX_CP_FIFO_BLOCK + 0x1C, high);
    }
    if platform::read_u8(SDA_GX_GP_ACTIVE) == 0 {
        if platform::read_u8(SDA_GX_TOKEN_DIRTY_A) != 0 {
            let mut outstanding = platform::read_u32(GX_GP_FIFO_BLOCK + 0x18)
                .wrapping_sub(platform::read_u32(GX_GP_FIFO_BLOCK + 0x14));
            if (outstanding as i32) < 0 {
                outstanding = outstanding.wrapping_add(platform::read_u32(GX_GP_FIFO_BLOCK + 8));
            }
            platform::write_u32(GX_GP_FIFO_BLOCK + 0x1C, outstanding);
        }
    } else {
        platform::write_u32(GX_GP_FIFO_BLOCK + 0x14, platform::read_u32(GX_CP_FIFO_BLOCK + 0x14));
        platform::write_u32(GX_GP_FIFO_BLOCK + 0x1C, platform::read_u32(GX_CP_FIFO_BLOCK + 0x1C));
        platform::write_u32(GX_CP_FIFO_BLOCK + 0x18, platform::read_u32(GX_GP_FIFO_BLOCK + 0x18));
        let busy = platform::read_u8(GX_GP_FIFO_BLOCK + 0x20);
        let control = platform::read_u32(GX_CP_FIFO_BLOCK + 0x20);
        platform::write_u32(GX_CP_FIFO_BLOCK + 0x20, (control & 0xFFFF_FF00) | busy as u32);
    }
    restore_interrupts(token);
}

/// Commits the GP FIFO block into the CP block and the hardware mirror.
///
/// # Original
/// - Ghidra: `FUN_801c35c0` at `0x801C35C0` (416 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801c35c0_FUN_801c35c0.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Returns immediately unless the second token flag is set. Under the
/// interrupt lock it clears the two `+8` state bits, moves the CP limit into
/// `GP+0x14`, zeroes `GP+0x1C` and the mirror's `+0x30..+0x3A` pairs, drains
/// the FIFO (`0x801A9B90`), and in commit mode copies the CP limit/state back
/// into the GP block and pulses the `+8` state bits.
///
/// # Safety
/// All blocks, the mirror and the small-data flags must be writable.
///
/// # Confidence
/// medium - the stores, masks and the drain call are literal; the mode flag
/// and field roles are inferred.
pub unsafe fn fn_801c35c0() {
    if platform::read_u8(SDA_GX_TOKEN_DIRTY_B) == 0 {
        return;
    }
    let token = disable_interrupts();
    let state = gx_state_base();
    let mut word = platform::read_u32(state + 8) & 0xFFFF_FFFE;
    platform::write_u32(state + 8, word);
    gx_mirror_status(word);
    word = platform::read_u32(state + 8) & 0xFFFF_FFF3;
    platform::write_u32(state + 8, word);
    gx_mirror_status(word);
    platform::write_u32(GX_GP_FIFO_BLOCK + 0x14, platform::read_u32(GX_CP_FIFO_BLOCK + 0x18));
    platform::write_u32(GX_GP_FIFO_BLOCK + 0x1C, 0);
    let block = platform::read_u32(SDA_GX_STATUS_BLOCK) as usize;
    platform::write_u16(block + 0x30, 0);
    platform::write_u16(block + 0x34, platform::read_u32(GX_CP_FIFO_BLOCK + 0x18) as u16);
    platform::write_u16(block + 0x38, platform::read_u32(GX_GP_FIFO_BLOCK + 0x14) as u16);
    platform::write_u16(block + 0x32, platform::read_u32(GX_GP_FIFO_BLOCK + 0x1C) as u16);
    platform::write_u16(
        block + 0x36,
        ((platform::read_u32(GX_CP_FIFO_BLOCK + 0x18) >> 16) & 0x3FFF) as u16,
    );
    platform::write_u16(
        block + 0x3A,
        ((platform::read_u32(GX_GP_FIFO_BLOCK + 0x14) >> 16) & 0x3FFF) as u16,
    );
    platform::call0(GX_FIFO_DRAIN);
    if platform::read_u8(SDA_GX_GP_ACTIVE) != 0 {
        platform::write_u32(GX_GP_FIFO_BLOCK + 0x14, platform::read_u32(GX_CP_FIFO_BLOCK + 0x14));
        platform::write_u32(GX_GP_FIFO_BLOCK + 0x18, platform::read_u32(GX_CP_FIFO_BLOCK + 0x18));
        platform::write_u32(GX_GP_FIFO_BLOCK + 0x1C, platform::read_u32(GX_CP_FIFO_BLOCK + 0x1C));
        let regs = platform::read_u32(SDA_GX_GP_REGS) as usize;
        platform::write_u32(
            regs + 0x14,
            platform::read_u32(GX_CP_FIFO_BLOCK + 0x18) & 0x1FFF_FFE0,
        );
        word = platform::read_u32(state + 8) & 0xFFFF_FFF7 | 4;
        platform::write_u32(state + 8, word);
        gx_mirror_status(word);
        word = platform::read_u32(state + 8) | 0x10;
        platform::write_u32(state + 8, word);
        gx_mirror_status(word);
    }
    word = platform::read_u32(state + 8) & 0xFFFF_FFDD;
    platform::write_u32(state + 8, word);
    gx_mirror_status(word);
    platform::write_u32(SDA_GX_EXTRA_COUNT, 0);
    word = platform::read_u32(state + 0x10) | 3;
    platform::write_u32(state + 0x10, word);
    platform::write_u16(block + 4, word as u16);
    word = platform::read_u32(state + 8) | 1;
    platform::write_u32(state + 8, word);
    gx_mirror_status(word);
    restore_interrupts(token);
}

/// `r13 - 0x60C8`: byte table of texture-size codes, indexed by the 2-bit
/// texgen type fields. `// inferred:`
const SDA_GX_TEX_SIZE_A: usize = SDA_BASE - 0x60C8;
/// `r13 - 0x60D0`: second byte table of texture-size codes. `// inferred:`
const SDA_GX_TEX_SIZE_B: usize = SDA_BASE - 0x60D0;
/// `r13 - 0x60CC`: byte table of texcoord-size codes, indexed by the 2-bit
/// texcoord fields. `// inferred:`
const SDA_GX_TEX_SIZE_C: usize = SDA_BASE - 0x60CC;

/// Writes one texturing selector into the `+0x14`/`+0x18` bit fields.
///
/// This is the 21-case switch on its own; the shared tail that both callers
/// run afterwards is [`gx_selector_tail`].
///
/// # Arguments
/// * `state` - GX state block base.
/// * `selector` - 0-8 = texgen enable bits, 9/11/12 = texgen size fields,
///   10/25 = CLUT format, 13-20 = texcoord size fields.
/// * `value` - raw value; each case applies its own mask.
///
/// # Safety
/// The GX state block must be writable.
#[inline]
unsafe fn gx_write_selector(state: usize, selector: u32, value: u32) {
    let mut at14 = platform::read_u32(state + 0x14);
    let mut at18 = platform::read_u32(state + 0x18);
    match selector {
        0x00 => at14 = (value & 1) | (at14 & 0xFFFF_FFFE),
        0x01 => at14 = ((value & 1) << 1) | (at14 & 0xFFFF_FFFD),
        0x02 => at14 = ((value & 1) << 2) | (at14 & 0xFFFF_FFFB),
        0x03 => at14 = ((value & 1) << 3) | (at14 & 0xFFFF_FFF7),
        0x04 => at14 = ((value & 1) << 4) | (at14 & 0xFFFF_FFEF),
        0x05 => at14 = ((value & 1) << 5) | (at14 & 0xFFFF_FFDF),
        0x06 => at14 = ((value & 1) << 6) | (at14 & 0xFFFF_FFBF),
        0x07 => at14 = ((value & 1) << 7) | (at14 & 0xFFFF_FF7F),
        0x08 => at14 = ((value & 1) << 8) | (at14 & 0xFFFF_FEFF),
        0x09 => at14 = ((value & 3) << 9) | (at14 & 0xFFFF_F9FF),
        0x0A => {
            if value == 0 {
                platform::write_u8(state + 0x524, 0);
            } else {
                platform::write_u8(state + 0x524, 1);
                platform::write_u8(state + 0x525, 0);
                platform::write_u32(state + 0x520, value);
            }
        }
        0x0B => at14 = ((value & 3) << 13) | (at14 & 0xFFFF_9FFF),
        0x0C => at14 = ((value & 3) << 15) | (at14 & 0xFFFE_7FFF),
        0x0D => at18 = (value & 3) | (at18 & 0xFFFF_FFFC),
        0x0E => at18 = ((value & 3) << 2) | (at18 & 0xFFFF_FFF3),
        0x0F => at18 = ((value & 3) << 4) | (at18 & 0xFFFF_FFCF),
        0x10 => at18 = ((value & 3) << 6) | (at18 & 0xFFFF_FF3F),
        0x11 => at18 = ((value & 3) << 8) | (at18 & 0xFFFF_FCFF),
        0x12 => at18 = ((value & 3) << 10) | (at18 & 0xFFFF_F3FF),
        0x13 => at18 = ((value & 3) << 12) | (at18 & 0xFFFF_CFFF),
        0x14 => at18 = ((value & 3) << 14) | (at18 & 0xFFFF_3FFF),
        0x19 => {
            if value == 0 {
                platform::write_u8(state + 0x525, 0);
            } else {
                platform::write_u8(state + 0x525, 1);
                platform::write_u8(state + 0x524, 0);
                platform::write_u32(state + 0x520, value);
            }
        }
        _ => {}
    }
    platform::write_u32(state + 0x14, at14);
    platform::write_u32(state + 0x18, at18);
}

/// Shared tail of the two selector writers.
///
/// Folds the CLUT format into bit 11 of `+0x14` and sets bit 3 of the dirty
/// word `+0x5FC`.
///
/// # Safety
/// The GX state block must be writable.
#[inline]
unsafe fn gx_selector_tail(state: usize) {
    // observed: both callers run this once, after the switch (and, for the
    // table form, after the whole loop).
    let mut at14 = platform::read_u32(state + 0x14);
    if platform::read_u8(state + 0x524) == 0 && platform::read_u8(state + 0x525) == 0 {
        at14 &= 0xFFFF_E7FF;
    } else {
        at14 = ((platform::read_u32(state + 0x520) & 3) << 11) | (at14 & 0xFFFF_E7FF);
    }
    platform::write_u32(state + 0x14, at14);
    platform::write_u32(state + 0x5FC, platform::read_u32(state + 0x5FC) | 8);
}

/// Reads one texturing selector back out of the `+0x14`/`+0x18` bit fields.
///
/// # Arguments
/// * `state` - GX state block base.
/// * `selector` - same numbering as [`gx_write_selector`].
///
/// # Returns
/// The masked field, or `0` for an unknown selector (and for the two CLUT
/// selectors when their dirty flag at `+0x524`/`+0x525` is clear).
///
/// # Safety
/// The GX state block must be readable.
#[inline]
unsafe fn gx_read_selector(state: usize, selector: u32) -> u32 {
    let at14 = platform::read_u32(state + 0x14);
    let at18 = platform::read_u32(state + 0x18);
    match selector {
        0x00..=0x08 => (at14 >> selector) & 1,
        0x09 => (at14 >> 9) & 3,
        0x0A => {
            if platform::read_u8(state + 0x524) == 0 {
                0
            } else {
                (at14 >> 11) & 3
            }
        }
        0x0B => (at14 >> 13) & 3,
        0x0C => (at14 >> 15) & 3,
        0x0D..=0x14 => (at18 >> (2 * (selector - 0x0D))) & 3,
        0x19 => {
            if platform::read_u8(state + 0x525) == 0 {
                0
            } else {
                (at14 >> 11) & 3
            }
        }
        _ => 0,
    }
}

/// Sets one texturing selector from an immediate value.
///
/// # Original
/// - Ghidra: `FUN_801c37c0` at `0x801C37C0` (612 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801c37c0_FUN_801c37c0.c`
///
/// # Arguments
/// * `selector` - 0-8 texgen enables, 9/11/12 texgen sizes, 10/25 CLUT
///   format, 13-20 texcoord sizes.
/// * `value` - raw value, masked per selector.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Updates `state+0x14`/`+0x18` (and `+0x520`/`+0x524`/`+0x525` for the CLUT
/// selectors), folds the CLUT format into bit 11 and sets bit 3 of `+0x5FC`.
///
/// # Safety
/// The GX state block must be writable.
///
/// # Confidence
/// high - the 21-case switch and the shared tail are literal; the field roles
/// are inferred from the sibling readers.
pub unsafe fn fn_801c37c0(selector: u32, value: u32) {
    let state = gx_state_base();
    gx_write_selector(state, selector, value);
    gx_selector_tail(state);
}

/// Applies a whole `(selector, value)` table.
///
/// # Original
/// - Ghidra: `FUN_801c3a30` at `0x801C3A30` (524 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801c3a30_FUN_801c3a30.c`
///
/// # Arguments
/// * `table` - pairs of `u32`: selector, value; terminated by selector `0xFF`.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Same per-entry effects as [`fn_801c37c0`], plus one shared tail after the
/// loop (CLUT fold and `+0x5FC` bit 3).
///
/// # Safety
/// `table` must be readable up to and including the `0xFF` terminator.
///
/// # Confidence
/// high - the loop and the shared tail are literal; the case bodies are the
/// same switch as `0x801C37C0`.
pub unsafe fn fn_801c3a30(table: usize) {
    let state = gx_state_base();
    let mut at = table;
    while platform::read_u32(at) != 0xFF {
        gx_write_selector(state, platform::read_u32(at), platform::read_u32(at + 4));
        at += 8;
    }
    // observed: the tail runs once after the loop, not per entry.
    gx_selector_tail(state);
}

/// Emits the derived texture-count command `0x21`.
///
/// # Original
/// - Ghidra: `FUN_801c3c40` at `0x801C3C40` (176 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801c3c40_FUN_801c3c40.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Writes one word to `0xCC008000` and sets the dirty marker at `state + 2`.
///
/// # Safety
/// The GX state block and the FIFO must be mapped.
///
/// # Confidence
/// medium - the shifts, the two `countLeadingZeros` calls and the FIFO store
/// are literal; the meaning of the packed fields is inferred.
pub unsafe fn fn_801c3c40() {
    let state = gx_state_base();
    let clut = if platform::read_u8(state + 0x525) == 0 {
        (platform::read_u8(state + 0x524) != 0) as u32
    } else {
        2
    };
    let size_a = (platform::read_u32(state + 0x14) >> 13 & 0xF).leading_zeros() as i32;
    let size_b = (platform::read_u32(state + 0x18) & 0xFFFF).leading_zeros() as i32;
    let word = ((((0x21 - size_b) * 8) as u32) & 0xFFFF_FFF0)
        | (((0x21 - size_a) as u32) >> 1)
        | (clut << 2);
    gx_fifo_write(word);
    platform::write_u16(state + 2, 1);
}

/// Sums the texture and texcoord size codes into `state + 6`.
///
/// # Original
/// - Ghidra: `FUN_801c3cf0` at `0x801C3CF0` (300 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801c3cf0_FUN_801c3cf0.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// When the half-word at `state + 4` is non-zero, stores the total into
/// `state + 6`. The total is the first nine texgen fields, four size-code
/// lookups from the two `r13` texgen tables (one of them weighted by the
/// `+0x1C` bit 9 field) plus two more, and eight texcoord size-code lookups.
///
/// # Safety
/// The state block and the three byte tables must be readable.
///
/// # Confidence
/// medium - the summation is literal; the table roles and the `3x` weight are
/// inferred from the neighbouring gen-mode writers.
pub unsafe fn fn_801c3cf0() {
    let state = gx_state_base();
    if platform::read_u16(state + 4) == 0 {
        return;
    }
    let texgen = platform::read_u32(state + 0x14);
    let texcoord = platform::read_u32(state + 0x18);
    let weight = if (platform::read_u32(state + 0x1C) >> 9) & 1 == 1 {
        3u16
    } else {
        1u16
    };
    let mut total = 0u16;
    // observed: the first nine fields are single enable bits.
    let mut bit = 0;
    while bit < 9 {
        total = total.wrapping_add(((texgen >> bit) & 1) as u16);
        bit += 1;
    }
    total = total
        .wrapping_add(platform::read_u8(SDA_GX_TEX_SIZE_A + ((texgen >> 9) & 3) as usize) as u16);
    total = total.wrapping_add(
        (platform::read_u8(SDA_GX_TEX_SIZE_A + ((texgen >> 11) & 3) as usize) as u16)
            .wrapping_mul(weight),
    );
    total = total
        .wrapping_add(platform::read_u8(SDA_GX_TEX_SIZE_B + ((texgen >> 13) & 3) as usize) as u16);
    total = total
        .wrapping_add(platform::read_u8(SDA_GX_TEX_SIZE_B + ((texgen >> 15) & 3) as usize) as u16);
    let mut field = 0;
    while field < 8 {
        total = total.wrapping_add(
            platform::read_u8(SDA_GX_TEX_SIZE_C + ((texcoord >> (2 * field)) & 3) as usize) as u16,
        );
        field += 1;
    }
    platform::write_u16(state + 6, total);
}

