/// Writes one per-stage texture record.
///
/// The record base is `state + index*4`; selectors 9-13 use the `+0x1C` word,
/// 14-17 use `+0x3C` and 18-20 use `+0x5C`.
///
/// # Arguments
/// * `state` - GX state block base.
/// * `index` - stage index (0-7), scaled by four.
/// * `selector` - 9-20; anything else is ignored.
/// * `a` - first field (mostly a one-bit enable).
/// * `b` - three-bit field.
/// * `c` - five-bit field (carries the raw stage count in some cases).
///
/// # Safety
/// The GX state block must be writable.
#[inline]
unsafe fn gx_write_stage(state: usize, index: u32, selector: u32, a: u32, b: u32, c: u32) {
    let base = state + (index as usize) * 4;
    let mut at1c = platform::read_u32(base + 0x1C);
    let mut at3c = platform::read_u32(base + 0x3C);
    let mut at5c = platform::read_u32(base + 0x5C);
    match selector {
        0x09 => at1c = ((c & 0x1F) << 4) | ((b & 7) << 1) | (a & 1) | (at1c & 0xFFFF_FE00),
        0x0A | 0x19 => {
            at1c = ((b & 7) << 10) | (at1c & 0xFFFF_E3FF);
            if a == 2 {
                at1c |= 0x8000_0200;
            } else {
                at1c = ((a & 1) << 9) | (at1c & 0x7FFF_FDFF);
            }
        }
        0x0B => at1c = ((b & 7) << 14) | ((a & 1) << 13) | (at1c & 0xFFFE_1FFF),
        0x0C => at1c = ((b & 7) << 18) | ((a & 1) << 17) | (at1c & 0xFFE1_FFFF),
        0x0D => {
            at1c = ((c & 0x1F) << 25) | ((b & 7) << 22) | ((a & 1) << 21) | (at1c & 0xC01F_FFFF)
        }
        0x0E => at3c = ((c & 0x1F) << 4) | ((b & 7) << 1) | (a & 1) | (at3c & 0xFFFF_FE00),
        0x0F => at3c = ((c & 0x1F) << 13) | ((b & 7) << 10) | ((a & 1) << 9) | (at3c & 0xFFFC_01FF),
        0x10 => {
            at3c = ((c & 0x1F) << 22) | ((b & 7) << 19) | ((a & 1) << 18) | (at3c & 0xF803_FFFF)
        }
        0x11 => {
            at3c = ((b & 7) << 28) | ((a & 1) << 27) | (at3c & 0x87FF_FFFF);
            at5c = (c & 0x1F) | (at5c & 0xFFFF_FFE0);
        }
        0x12 => at5c = ((c & 0x1F) << 9) | ((b & 7) << 6) | ((a & 1) << 5) | (at5c & 0xFFFF_C01F),
        0x13 => at5c = ((c & 0x1F) << 18) | ((b & 7) << 15) | ((a & 1) << 14) | (at5c & 0xFF80_3FFF),
        0x14 => at5c = (c << 27) | ((b & 7) << 24) | ((a & 1) << 23) | (at5c & 0x007F_FFFF),
        _ => return,
    }
    platform::write_u32(base + 0x1C, at1c);
    platform::write_u32(base + 0x3C, at3c);
    platform::write_u32(base + 0x5C, at5c);
}

/// Shared tail of the two per-stage writers: sets bit 4 of `+0x5FC` and the
/// stage's bit in the `+0x5FB` dirty mask.
///
/// # Safety
/// The GX state block must be writable.
#[inline]
unsafe fn gx_stage_dirty_tail(state: usize, index: u32) {
    platform::write_u32(state + 0x5FC, platform::read_u32(state + 0x5FC) | 0x10);
    // observed: the export forms the mask with a 32-bit `1 << index` and then
    // truncates it to a byte.
    let bit = 1u32.wrapping_shl(index) as u8;
    platform::write_u8(state + 0x5FB, platform::read_u8(state + 0x5FB) | bit);
}

/// Reads one per-stage texture record back out of the state block.
///
/// # Arguments
/// * `state` - GX state block base.
/// * `index` - stage index (0-7).
/// * `selector` - 9-20.
///
/// # Returns
/// `(a, b, c)` for the selector; `(1, 0, 0)` for an unknown selector.
///
/// # Safety
/// The GX state block must be readable.
#[inline]
unsafe fn gx_read_stage(state: usize, index: u32, selector: u32) -> (u32, u32, u32) {
    let base = state + (index as usize) * 4;
    let at1c = platform::read_u32(base + 0x1C);
    let at3c = platform::read_u32(base + 0x3C);
    let at5c = platform::read_u32(base + 0x5C);
    match selector {
        0x09 => (at1c & 1, (at1c >> 1) & 7, (at1c >> 4) & 0x1F),
        0x0A | 0x19 => {
            let mut a = (at1c >> 9) & 1;
            if a == 1 && (at1c as i32) < 0 {
                a = 2;
            }
            let b = (at1c >> 10) & 7;
            let c = match b {
                1 => 6,
                3 => 0xE,
                _ => 0,
            };
            (a, b, c)
        }
        0x0B => ((at1c >> 13) & 1, (at1c >> 14) & 7, 0),
        0x0C => ((at1c >> 17) & 1, (at1c >> 18) & 7, 0),
        0x0D => ((at1c >> 21) & 1, (at1c >> 22) & 7, (at1c >> 25) & 0x1F),
        0x0E => (at3c & 1, (at3c >> 1) & 7, (at3c >> 4) & 0x1F),
        0x0F => ((at3c >> 9) & 1, (at3c >> 10) & 7, (at3c >> 13) & 0x1F),
        0x10 => ((at3c >> 18) & 1, (at3c >> 19) & 7, (at3c >> 22) & 0x1F),
        0x11 => ((at3c >> 27) & 1, (at3c >> 28) & 7, at5c & 0x1F),
        0x12 => ((at5c >> 5) & 1, (at5c >> 6) & 7, (at5c >> 9) & 0x1F),
        0x13 => ((at5c >> 14) & 1, (at5c >> 15) & 7, (at5c >> 18) & 0x1F),
        0x14 => ((at5c >> 23) & 1, (at5c >> 24) & 7, at5c >> 27),
        _ => (1, 0, 0),
    }
}

