/// `r13 - 0x4DE4`: pointer to the video-interface register window whose
/// half-word at `+0x4E` free-runs; polled by the two synchronised waits.
/// `// inferred:`
const SDA_VI_REGS: usize = SDA_BASE - 0x4DE4;

/// `r13 - 0x4DA0`: "retrace finished" byte, cleared by [`fn_801c4ea0`] and
/// set by the handler [`fn_801c5200`]. `// inferred:`
const SDA_GX_RETRACE_DONE: usize = SDA_BASE - 0x4DA0;

/// `r13 - 0x4D98`: first retrace callback pointer, invoked by
/// [`fn_801c5120`] with the IRQ block's `+0xE` half-word. `// inferred:`
const SDA_GX_RETRACE_CALLBACK_B: usize = SDA_BASE - 0x4D98;

/// `0xCC003018`: word-wide MMIO latch pulsed 1 then 0 around the two short
/// tick delays in [`fn_801c4b70`]/[`fn_801c4ce0`]. `// unknown:` the exact
/// register name is not established by the export.
const MMIO_CC003018: usize = 0xCC00_3018;

/// `0x801B5D80`: wakes one thread waiting on a queue.
const OS_WAKEUP_THREAD: usize = 0x801B_5D80;

/// `0x801C78D0`: texture-register flush step selected by dirty bit 0.
const GX_FLUSH_STEP_0: usize = 0x801C_78D0;
/// `0x801C81E0`: flush step selected by dirty bit 1.
const GX_FLUSH_STEP_1: usize = 0x801C_81E0;
/// `0x801C9D90`: per-stage flush step selected by dirty bit `0x4000000`.
const GX_FLUSH_STEP_STAGE: usize = 0x801C_9D90;
/// `0x801C9B40`: flush step selected by dirty bit `0x10000000`.
const GX_FLUSH_STEP_28: usize = 0x801C_9B40;
/// `0x801C97F0`: flush step selected by dirty bit `0x8000000`.
const GX_FLUSH_STEP_27: usize = 0x801C_97F0;
/// `0x801C1C80`: texture-state reset run by [`fn_801c4ce0`] after the commit.
const GX_TEX_STATE_RESET: usize = 0x801C_1C80;

/// Waits until the VI counter half-word stops changing and returns the whole
/// word read alongside the final sample.
///
/// # Safety
/// `vi` must address the video-interface register window.
#[inline]
unsafe fn gx_wait_vi_stable(vi: usize) -> u32 {
    let mut last = platform::read_u16(vi + 0x4E);
    loop {
        let now = platform::read_u16(vi + 0x4E);
        let word = platform::read_u32(vi + 0x4E);
        let changed = now != last;
        last = now;
        if !changed {
            return word;
        }
    }
}

/// Busy-waits until at least `ticks` have elapsed on the 64-bit timebase.
///
/// # Safety
/// The timebase reader must be callable.
#[inline]
unsafe fn gx_wait_ticks(ticks: u64) {
    let start = platform::call_u64(OS_GET_TICK_64);
    while platform::call_u64(OS_GET_TICK_64).wrapping_sub(start) <= ticks {}
}

/// Sets one texcoord-generation record.
///
/// # Original
/// - Ghidra: `FUN_801c47d0` at `0x801C47D0` (580 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801c47d0_FUN_801c47d0.c`
///
/// # Arguments
/// * `index` - texcoord index 0-7 (scaled by four internally).
/// * `kind` - generation type id; 0-0xB and 0x13/0x14 are mapped to a size
///   code, everything else falls back to code 5.
/// * `format` - second type id; `kind - 0xC` becomes the `0x1000` field and
///   `format == 0x13` selects the `0x20` variant of the `kind == 10` case.
/// * `bias` - six-bit field written to `state + 0x80`/`+0x84`.
/// * `clamp` - one-bit field.
/// * `scale` - six-bit value stored biased by `0x40`.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Stores `+0xC8` and `+0xE8` of the per-index record, sets `0x10000 << index`
/// and `0x4000000` in `+0x5FC`, and writes the `+0x80`/`+0x84` bias field.
///
/// # Safety
/// The GX state block must be writable.
///
/// # Confidence
/// medium - every mask and store is literal; the field meanings are inferred
/// from the neighbouring texcoord writers.
pub unsafe fn fn_801c47d0(
    index: u32,
    kind: u32,
    format: u32,
    bias: u32,
    clamp: u32,
    scale: u32,
) {
    let (code, flag) = match kind {
        0 => (0u32, 1u32),
        1 => (1, 1),
        2 => (3, 1),
        3 => (4, 1),
        4 => (5, 0),
        5 => (6, 0),
        6 => (7, 0),
        7 => (8, 0),
        8 => (9, 0),
        9 => (10, 0),
        10 => (11, 0),
        11 => (12, 0),
        0x13 => (2, 0),
        0x14 => (2, 0),
        _ => (5, 0),
    };
    let mut word = 0u32;
    if kind.wrapping_sub(2) < 8 {
        word = (kind.wrapping_sub(2).wrapping_mul(0x8000) & 0x0003_8000)
            | (format.wrapping_sub(0xC).wrapping_mul(0x1000) & 0x0000_7000)
            | (code << 7)
            | (flag << 2)
            | 0x10;
    } else if kind == 1 {
        word = (code << 7) | (flag << 2);
    } else if kind == 0 {
        word = (code << 7) | (flag << 2) | 2;
    } else if kind == 10 {
        let base = if format == 0x13 { 0x20 } else { 0x30 };
        word = base | (flag << 2) | 0x100;
    }
    let state = gx_state_base();
    let base = state + (index as usize) * 4;
    platform::write_u32(base + 0xC8, word);
    platform::write_u32(
        state + 0x5FC,
        platform::read_u32(state + 0x5FC) | 0x1_0000u32.wrapping_shl(index),
    );
    platform::write_u32(
        base + 0xE8,
        ((clamp & 1) << 8) | (scale.wrapping_sub(0x40) & 0x3F),
    );
    // observed: the eight texcoord bias fields are packed six bits at a time
    // into `+0x80` (indices 0-3) and `+0x84` (indices 4-7).
    let field = if index < 4 { state + 0x80 } else { state + 0x84 };
    let shift = (index & 3) * 6;
    let old = platform::read_u32(field);
    platform::write_u32(field, ((bias & 0x3F) << shift) | (old & !(0x3F << shift)));
    platform::write_u32(state + 0x5FC, platform::read_u32(state + 0x5FC) | 0x0400_0000);
}

/// Stores the texgen/texcoord count word or an indirect-stage flag.
///
/// # Original
/// - Ghidra: `FUN_801c4a50` at `0x801C4A50` (128 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801c4a50_FUN_801c4a50.c`
///
/// # Arguments
/// * `kind` - `1` writes the count word, `2` and `3` write one indirect-stage
///   flag byte each; other values are ignored.
/// * `value` - count (kind 1) or flag word (kind 2/3).
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Writes `state+0`, `+2`, `+4` and, when the count is non-zero, sets bit 3 of
/// `+0x5FC`. Indirect writes go to `+0x5F9`/`+0x5FA`.
///
/// # Safety
/// The GX state block must be writable.
///
/// # Confidence
/// medium - the stores and the leading-zero test are literal; the two flag
/// bytes' meaning is inferred.
pub unsafe fn fn_801c4a50(kind: u32, value: u32) {
    let state = gx_state_base();
    if kind == 1 {
        platform::write_u16(state + 4, value as u16);
        platform::write_u16(state, ((value & 0xFFFF).leading_zeros() >> 5) as u16);
        platform::write_u16(state + 2, 1);
        if value & 0xFFFF == 0 {
            return;
        }
        platform::write_u32(state + 0x5FC, platform::read_u32(state + 0x5FC) | 8);
        return;
    }
    // observed: the export builds the byte as the OR of the top bytes of
    // `value` and `-value`, shifted right by seven, i.e. "value is neither 0
    // nor 0x80000000".
    let byte = (((value >> 24) as u8) | ((value.wrapping_neg() >> 24) as u8)) >> 7;
    if kind == 2 {
        platform::write_u8(state + 0x5F9, byte);
    } else if kind == 3 {
        platform::write_u8(state + 0x5FA, byte);
    }
}

/// Waits for two stable VI samples, pulses `0xCC003018`, and waits again.
///
/// # Original
/// - Ghidra: `FUN_801c4b70` at `0x801C4B70` (356 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801c4b70_FUN_801c4b70.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// When `state + 0x5FA` and the token flag are both set, waits for the VI
/// counter to settle twice with an eight-tick gap between the samples. Then
/// writes `1` and `0` to `0xCC003018` with waits of `0x32` and `5` ticks.
///
/// # Safety
/// The VI window, the state block and the MMIO latch must be mapped.
///
/// # Confidence
/// medium - the loops and the MMIO stores are literal; the export opens with a
/// Metrowerks register-save stub, which is omitted because it has no effect.
pub unsafe fn fn_801c4b70() {
    let state = gx_state_base();
    if platform::read_u8(state + 0x5FA) != 0 && fn_801c33e0() != 0 {
        let vi = platform::read_u32(SDA_VI_REGS) as usize;
        let mut snapshot = gx_wait_vi_stable(vi);
        loop {
            gx_wait_ticks(8);
            let next = gx_wait_vi_stable(vi);
            let changed = next != snapshot;
            snapshot = next;
            if !changed {
                break;
            }
        }
    }
    platform::write_u32(MMIO_CC003018, 1);
    gx_wait_ticks(0x32);
    platform::write_u32(MMIO_CC003018, 0);
    gx_wait_ticks(5);
}

/// Same VI synchronisation as [`fn_801c4b70`], then commits and resets the
/// texture state.
///
/// # Original
/// - Ghidra: `FUN_801c4ce0` at `0x801C4CE0` (432 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801c4ce0_FUN_801c4ce0.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Runs the two-sample wait, pulses `0xCC003018`, and when the token flag is
/// still set calls [`fn_801c35c0`] and `0x801C1C80`, clears `+0x5FC`, writes a
/// zero word to the FIFO and drains it.
///
