/// Flushes the FIFO and blocks until the retrace handler reports completion.
///
/// # Original
/// - Ghidra: `FUN_801c4ea0` at `0x801C4EA0` (204 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801c4ea0_FUN_801c4ea0.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Emits `0x45000002`, runs the dirty-state dispatcher when `+0x5FC` is
/// non-zero, emits a zero word and drains, clears the retrace byte under the
/// interrupt lock, clears `state + 2`, and then sleeps on the GX wait queue
/// until [`fn_801c5200`] sets the retrace byte.
///
/// # Safety
/// The GX blocks, the FIFO and the wait queue must be mapped.
///
/// # Confidence
/// medium - the stores, the two lock sections and the sleep call are literal.
pub unsafe fn fn_801c4ea0() {
    let token = disable_interrupts();
    let state = gx_state_base();
    gx_fifo_write(0x4500_0002);
    if platform::read_u32(state + 0x5FC) != 0 {
        platform::call0(GX_DRAW_COMPLETE_WAIT);
    }
    gx_fifo_write(0);
    platform::call0(GX_FIFO_DRAIN);
    platform::write_u8(SDA_GX_RETRACE_DONE, 0);
    restore_interrupts(token);
    platform::write_u16(state + 2, 0);
    let token = disable_interrupts();
    while platform::read_u8(SDA_GX_RETRACE_DONE) == 0 {
        platform::call1(OS_SLEEP_THREAD, SDA_GX_WAIT_QUEUE as u32);
    }
    restore_interrupts(token);
}

/// First retrace handler: acknowledges one IRQ source and runs the registered
/// callback with the IRQ block's `+0xE` half-word.
///
/// # Original
/// - Ghidra: `FUN_801c5120` at `0x801C5120` (132 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801c5120_FUN_801c5120.c`
///
/// # Arguments
/// * `_arg` - unused by the body.
/// * `restore_arg` - passed to the DSP restore helper after the callback.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Saves and restores the DSP state around the callback, then sets bit 2 of
/// the IRQ block's `+0xA` half-word.
///
/// # Safety
/// The IRQ block, the callback pointer and the DSP helpers must be valid.
///
/// # Confidence
/// medium - the call order and the bit set are literal; the 0x2D0-byte stack
/// buffer is Ghidra's save area and is modelled as a local scratch buffer.
pub unsafe fn fn_801c5120(_arg: u32, restore_arg: u32) {
    let block = platform::read_u32(SDA_GX_IRQ_STATUS) as usize;
    let status = platform::read_u16(block + 0xE);
    let callback = platform::read_u32(SDA_GX_RETRACE_CALLBACK_B);
    if callback != 0 {
        let mut scratch = [0u8; 0x2D0];
        let area = scratch.as_mut_ptr() as u32;
        platform::call1(DSP_SAVECTL_A, area);
        platform::call1(DSP_SAVECTL_B, area);
        platform::call1(callback as usize, status as u32);
        platform::call1(DSP_SAVECTL_A, area);
        platform::call1(DSP_SAVECTL_B, restore_arg);
    }
    let control = platform::read_u16(block + 0xA);
    platform::write_u16(block + 0xA, control | 4);
}

/// Second retrace handler: marks completion, runs the retrace callback and
/// wakes the draw-complete waiter.
///
/// # Original
/// - Ghidra: `FUN_801c5200` at `0x801C5200` (128 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801c5200_FUN_801c5200.c`
///
/// # Arguments
/// * `_arg` - unused by the body.
/// * `restore_arg` - passed to the DSP restore helper after the callback.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Sets bit 3 of the IRQ block's `+0xA`, sets the retrace byte, runs the DSP
/// save/callback/restore sequence, and wakes the GX wait queue.
///
/// # Safety
/// The IRQ block, the callback pointer and the wait queue must be valid.
///
/// # Confidence
/// medium - the call order and the bit set are literal; the stack save area is
/// modelled as a local scratch buffer.
pub unsafe fn fn_801c5200(_arg: u32, restore_arg: u32) {
    let block = platform::read_u32(SDA_GX_IRQ_STATUS) as usize;
    let control = platform::read_u16(block + 0xA);
    platform::write_u16(block + 0xA, control | 8);
    platform::write_u8(SDA_GX_RETRACE_DONE, 1);
    let callback = platform::read_u32(SDA_GX_RETRACE_CALLBACK);
    if callback != 0 {
        let mut scratch = [0u8; 0x2D4];
        let area = scratch.as_mut_ptr() as u32;
        platform::call1(DSP_SAVECTL_A, area);
        platform::call1(DSP_SAVECTL_B, area);
        platform::call0(callback as usize);
        platform::call1(DSP_SAVECTL_A, area);
        platform::call1(DSP_SAVECTL_B, restore_arg);
    }
    platform::call1(OS_WAKEUP_THREAD, SDA_GX_WAIT_QUEUE as u32);
}

/// Dispatches every dirty texture/indirect-state group to the FIFO.
///
/// # Original
/// - Ghidra: `FUN_801c52f0` at `0x801C52F0` (632 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801c52f0_FUN_801c52f0.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Reads the dirty word at `state + 0x5FC` and emits, for each set group:
/// the `0x801C78D0`/`0x801C81E0` flush steps, the `+0x254` word, the derived
/// texture command ([`fn_801c3c40`]), the stage mask ([`fn_801c4420`]), the
/// size total ([`fn_801c3cf0`]), the four `+0xA8`-`+0xB4` TEV words, the
/// `+0xB8`/`+0xE8` per-stage loops, `0x801C9D90` for stages 0 and 5,
/// `0x801C9B40` and `0x801C97F0`. Finally sets `state + 2` and clears the
/// dirty word.
///
/// # Safety
/// The GX state block, the FIFO and all callees must be mapped.
///
/// # Confidence
/// high - every bit test, mask, FIFO store and call is literal.
pub unsafe fn fn_801c52f0() {
    let state = gx_state_base();
    let dirty = platform::read_u32(state + 0x5FC);
    if dirty & 0x1 != 0 {
        platform::call0(GX_FLUSH_STEP_0);
    }
    if dirty & 0x2 != 0 {
        platform::call0(GX_FLUSH_STEP_1);
    }
    if dirty & 0x4 != 0 {
        gx_fifo_write(platform::read_u32(state + 0x254));
        platform::write_u16(state + 2, 0);
    }
    if dirty & 0x8 != 0 {
        fn_801c3c40();
    }
    if dirty & 0x10 != 0 {
        fn_801c4420();
    }
    if dirty & 0x18 != 0 {
        fn_801c3cf0();
    }
    if dirty & 0xFFFF_FF00 != 0 {
        if dirty & 0xF00 != 0 {
            if dirty & 0x100 != 0 {
                gx_fifo_write(platform::read_u32(state + 0xA8));
            }
            if dirty & 0x200 != 0 {
                gx_fifo_write(platform::read_u32(state + 0xAC));
            }
            if dirty & 0x400 != 0 {
                gx_fifo_write(platform::read_u32(state + 0xB0));
            }
            if dirty & 0x800 != 0 {
                gx_fifo_write(platform::read_u32(state + 0xB4));
            }
        }
        if dirty & 0x0100_F000 != 0 {
            if dirty & 0x0100_0000 != 0 {
                gx_fifo_write((platform::read_u32(state + 0x254) >> 4) & 7);
            }
            let mut mask = (dirty & 0xF000) >> 12;
            let mut at = state;
            while mask != 0 {
                if mask & 1 != 0 {
                    gx_fifo_write(platform::read_u32(at + 0xB8));
                }
                mask >>= 1;
                at += 4;
            }
        }
        if dirty & 0x02FF_0000 != 0 {
            if dirty & 0x0200_0000 != 0 {
                gx_fifo_write(platform::read_u32(state + 0x254) & 0xF);
            }
            let mut mask = (dirty & 0x02FF_0000) >> 16 & 0xFF;
            let mut at = state;
            while mask != 0 {
                if mask & 1 != 0 {
                    gx_fifo_write(platform::read_u32(at + 0xE8));
                }
                mask >>= 1;
                at += 4;
            }
        }
        if dirty & 0x0400_0000 != 0 {
            platform::call1(GX_FLUSH_STEP_STAGE, 0);
            platform::call1(GX_FLUSH_STEP_STAGE, 5);
        }
        if dirty & 0x1000_0000 != 0 {
            platform::call0(GX_FLUSH_STEP_28);
        }
        if dirty & 0x0800_0000 != 0 {
            platform::call0(GX_FLUSH_STEP_27);
        }
        platform::write_u16(state + 2, 1);
    }
    platform::write_u32(state + 0x5FC, 0);
}

// ---------------------------------------------------------------------------
// Wave 87: the ISFS / NAND file API and the settings-store record core,
// `0x801D3260`-`0x801DDAB0`.
//
// The remaining `0x801D0000`-bucket addresses are dominated by the SDK's ISFS
// (internal flash file system) wrapper. Its shared state is the word at
// `r13 - 0x4C40` (0 idle, 1 mounting, 2 ready), its error mapper is
// `0x801DA570` over the 0x29-entry `(ISFS code, mapped error)` table at
// `0x802F6B34`, and the file wrappers are thin layers over the open/attribute
// cores `0x801D94A0`, `0x801D91C0` and `0x801D8E20`.
//
// The second half of the slice finishes the Wave 72 settings store:
// `0x801DC100` is the record decoder its readers already call through
// [`SETTINGS_PARSE_RECORD`], and the `0x801DD1D0`-`0x801DD6F0` group are the
// typed getters and the obfuscated text-block lookup used by the drive and
// channel configuration path.
//
// Four small DVD-band accessors lead the slice: they return the three static
// register/command images and one constant zero.
// ---------------------------------------------------------------------------

/// `r13 - 0x4C40`: ISFS bring-up state. `0` idle, `1` mounting, `2` ready;
/// every wrapper below refuses to run unless it reads `2`.
const ISFS_STATE: usize = SDA_BASE - 0x4C40;

/// `0x802F6B34`: 0x29-entry `(ISFS error code, mapped code)` table. The mapper
/// [`fn_801da570`] copies it to the stack before searching, exactly as the
/// export does.
const ISFS_ERROR_TABLE: usize = 0x802F_6B34;

/// Entry count of [`ISFS_ERROR_TABLE`] (`0x29` pairs, 0x148 bytes).
const ISFS_ERROR_PAIRS: usize = 0x29;

/// `0x80343690`: the eight-character prefix `"/shared2"`.
const ISFS_SHARED2: usize = 0x8034_3690;

/// `0x8034369C`: the nine-character prefix `"/shared2/"`.
const ISFS_SHARED2_SLASH: usize = 0x8034_369C;

/// `0x80343640`: path-format buffer. The mount path copies the home directory
/// into it (`0x801DA860`) and [`fn_801da6e0`] formats relative names through
/// it. `// inferred:` the buffer holds a `"%s/%s"`-shaped format string.
const ISFS_PATH_FORMAT: usize = 0x8034_3640;

/// `0x80395DE0`: home-directory string filled in by the mount path.
/// `// inferred:` the content is the flash root copied from `0x80343640`.
const ISFS_HOME_DIR: usize = 0x8039_5DE0;

/// `r13 - 0x5FF0`: small-data default path used when the caller's name is
/// empty. `// unknown:` the literal text lives in the small-data area and is
/// not visible in the export.
const SDA_ISFS_DEFAULT_PATH: usize = SDA_BASE - 0x5FF0;

/// `0x803436A8`: `"ISFS error code: %d"`.
const MSG_ISFS_ERROR_CODE: u32 = 0x8034_36A8;

/// `0x803436BC`: `"CAUTION: Unexpected error code %d"`.
const MSG_ISFS_CAUTION: u32 = 0x8034_36BC;

/// `0x803436F0`: `"ISFS unexpected error code %d"`.
const MSG_ISFS_UNEXPECTED: u32 = 0x8034_36F0;

/// `0x801D8E20`: two-path operation core (rename-shaped: it builds two paths
/// and calls the sync/async pair `0x80227040`/`0x80227150`). `// inferred:`
const ISFS_RENAME: usize = 0x801D_8E20;

/// `0x801D91C0`: file-attribute core. It fills a 0x20-byte stats block from
/// `0x80226BF0` (sync) or `0x80226D50` (async). `// inferred:`
