/// Maps an ISFS result code through the 0x29-entry error table.
///
/// # Original
/// - Ghidra: `FUN_801da570` at `0x801DA570` (360 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801da570_FUN_801da570.c`
///
/// # Arguments
/// * `error` - raw ISFS result code; non-negative codes pass through.
///
/// # Returns
/// The table's mapped code for a known negative code, `0xFFFFFFC0` for an
/// unknown negative code, or `error` unchanged when it is non-negative.
///
/// # Side effects
/// Copies the table to the stack, and for the five codes `-0x72`, `-0x74`,
/// `-0x75`, `-0x9` and `-0xC` formats and logs `"ISFS error code: %d"`.
/// Unknown codes additionally print the caution line through `0x8015F730`.
///
/// # Safety
/// The table and message strings must be readable; the error log writable.
///
/// # Confidence
/// medium - the copy, the search, the five-code set, the two formatted
/// messages and the `-0x40` fallback are literal; the callee identities are
/// inferred from the message text.
pub unsafe fn fn_801da570(error: u32) -> u32 {
    let mut table = [0u32; 0x52];
    let mut i = 0;
    while i < 0x52 {
        table[i] = platform::read_u32(ISFS_ERROR_TABLE + i * 4);
        i += 1;
    }
    let code = error as i32;
    if code < 0 {
        let mut entry = 0;
        while entry < ISFS_ERROR_PAIRS {
            if table[entry * 2] as i32 == code {
                if code == -0x72 || code == -0x74 || code == -0x75 || code == -0x9 || code == -0xC {
                    let mut text = [0u8; 0x80];
                    platform::call3(
                        SPRINTF,
                        text.as_mut_ptr() as u32,
                        MSG_ISFS_ERROR_CODE,
                        error,
                    );
                    platform::call2(ISFS_REPORT, 0, text.as_ptr() as u32);
                }
                return table[entry * 2 + 1];
            }
            entry += 1;
        }
        platform::call2(DVD_LOW_REPORT, MSG_ISFS_CAUTION, error);
        let mut text = [0u8; 0x80];
        platform::call3(
            SPRINTF,
            text.as_mut_ptr() as u32,
            MSG_ISFS_UNEXPECTED,
            error,
        );
        platform::call2(ISFS_REPORT, 0, text.as_ptr() as u32);
        return 0xFFFF_FFC0;
    }
    error
}

