/// Decodes one variable-length settings record into a 0x20-byte descriptor.
///
/// # Original
/// - Ghidra: `FUN_801dc100` at `0x801DC100` (384 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801dc100_FUN_801dc100.c`
///
/// # Arguments
/// * `record` - TLV record: a header byte (low five bits = name length, high
///   three bits = type) followed by the name and the payload.
/// * `desc` - 0x20-byte descriptor: `+0x0C` header length, `+0x10` payload
///   length, `+0x14` name, `+0x18` payload, `+0x1C` whole-record length.
///
/// # Returns
/// Non-zero when the type is known and a payload length was produced.
///
/// # Side effects
/// Zeroes `desc`, writes the five fields, marks `+9 = 0x40` for the two
/// variable-length types, and for the fixed types copies the payload over the
/// descriptor's first `length` bytes.
///
/// # Safety
/// `record` must hold the record and `desc` must be 0x20 writable bytes.
///
/// # Confidence
/// high - the masks, the six type cases, the two variable-length striding
/// rules and the `(-len | len) >> 31` return are literal.
pub unsafe fn fn_801dc100(record: usize, desc: usize) -> u32 {
    platform::call3(MEMSET, desc as u32, 0, 0x20);
    let header = platform::read_u8(record);
    let name_len = (header & 0x1F) as usize;
    let kind = header & 0xE0;
    platform::write_u32(desc + 0x14, record as u32 + 1);
    let payload = record + name_len + 2;
    platform::write_u32(desc + 0x0C, name_len as u32 + 1);
    platform::write_u32(desc + 0x18, payload as u32);
    match kind {
        // observed: one-byte, two-byte, four-byte and eight-byte fixed types.
        0x60 | 0xE0 => platform::write_u32(desc + 0x10, 1),
        0x80 => platform::write_u32(desc + 0x10, 2),
        0xA0 => platform::write_u32(desc + 0x10, 4),
        0xC0 => platform::write_u32(desc + 0x10, 8),
        // observed: variable-length types carry their length after the name.
        0x40 => {
            platform::write_u32(desc + 0x10, platform::read_u8(payload) as u32 + 1);
            platform::write_u32(desc + 0x18, payload as u32 + 1);
            let extra = platform::read_u32(desc + 0x1C) + 1;
            platform::write_u32(desc + 0x1C, extra);
        }
        0x20 => {
            platform::write_u32(desc + 0x10, platform::read_u16(payload) as u32 + 1);
            platform::write_u32(desc + 0x18, payload as u32 + 2);
            let extra = platform::read_u32(desc + 0x1C) + 2;
            platform::write_u32(desc + 0x1C, extra);
        }
        _ => {
            let len = platform::read_u32(desc + 0x10);
            return (0u32.wrapping_sub(len) | len) >> 31;
        }
    }
    if kind == 0x40 || kind == 0x20 {
        platform::write_u8(desc + 0x09, 0x40);
    } else {
        platform::write_u8(desc + 0x08, kind);
        platform::call3(
            MEMCPY,
            desc as u32,
            platform::read_u32(desc + 0x18),
            platform::read_u32(desc + 0x10),
        );
    }
    let total = platform::read_u32(desc + 0x0C)
        .wrapping_add(platform::read_u32(desc + 0x10))
        .wrapping_add(platform::read_u32(desc + 0x1C))
        .wrapping_add(1);
    platform::write_u32(desc + 0x1C, total);
    let len = platform::read_u32(desc + 0x10);
    (0u32.wrapping_sub(len) | len) >> 31
}

