    platform::write_f32(out + 0x04, zero);
    platform::write_f32(out + 0x08, zero);
    platform::write_f32(out + 0x0C, zero);
    platform::write_f32(out + 0x10, zero);
    platform::write_f32(out + 0x14, one);
    platform::write_f32(out + 0x18, zero);
    platform::write_f32(out + 0x1C, zero);
    platform::write_f32(out + 0x20, zero);
    platform::write_f32(out + 0x24, zero);
    platform::write_f32(out + 0x28, one);
    platform::write_f32(out + 0x2C, zero);
