    fn_801c1530(up, dir.as_ptr() as usize, right.as_mut_ptr() as usize);
    fn_801c1470(right.as_mut_ptr() as usize, right.as_mut_ptr() as usize);
    fn_801c1530(dir.as_ptr() as usize, right.as_ptr() as usize, upv.as_mut_ptr() as usize);

