    platform::write_f32(out + 0x04, right[1]);
    platform::write_f32(out + 0x08, right[2]);
    platform::write_f32(out + 0x0C, -(ez * right[2] + ex * right[0] + ey * right[1]));
    platform::write_f32(out + 0x10, upv[0]);
    platform::write_f32(out + 0x14, upv[1]);
    platform::write_f32(out + 0x18, upv[2]);
    platform::write_f32(out + 0x1C, -(ez * upv[2] + ex * upv[0] + ey * upv[1]));
    platform::write_f32(out + 0x20, dir[0]);
    platform::write_f32(out + 0x24, dir[1]);
    platform::write_f32(out + 0x28, dir[2]);
    platform::write_f32(out + 0x2C, -(ez * dir[2] + ex * dir[0] + ey * dir[1]));
