pub unsafe fn fn_801c7130(word: usize, index: u32, count: u32) {
    let old = platform::read_u32(word);
    let bit4 = (count.wrapping_sub(1).leading_zeros() >> 1) & 0x10;
    platform::write_u32(word, bit4 | (old & 0xFFFF_FFEF));
    let table = platform::read_u8(SDA_BASE - 0x6088 + index as usize);
    platform::write_u32(
        word,
        (((table & 7) as u32) << 5) | bit4 | (old & 0xFFFF_FF0F),
    );
}

/// Splits a texture-object descriptor into its output fields.
///
/// # Original
/// - Ghidra: `FUN_801c7180` at `0x801C7180` (84 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801c7180_FUN_801c7180.c`
///
/// # Arguments
/// * `this` - source object (read at `+0x00`, `+0x08`, `+0x0C`, `+0x14`,
///   `+0x1F`).
/// * `format` - receives `(this[3] & 0xFFFFFF) << 5`.
/// * `width` - receives `(this[2] & 0x3FF) + 1`.
/// * `height` - receives `((this[2] >> 10) & 0x3FF) + 1`.
/// * `field5` - receives `this[5]`.
/// * `field6` - receives `this[0] & 3`.
/// * `field7` - receives `(this[0] >> 2) & 3`.
/// * `flag` - receives bit 0 of the byte at `+0x1F`.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Writes six words, two half-words and one byte to the caller's pointers.
///
/// # Safety
/// All pointers must be valid for their declared width.
///
/// # Confidence
/// high - every mask and shift is literal.
#[allow(clippy::too_many_arguments)]
pub unsafe fn fn_801c7180(
    this: usize,
    format: usize,
    width: usize,
    height: usize,
    field5: usize,
    field6: usize,
    field7: usize,
    flag: usize,
) {
    let word0 = platform::read_u32(this);
    let word2 = platform::read_u32(this + 0x08);
    let word3 = platform::read_u32(this + 0x0C);
    platform::write_u32(format, (word3 & 0x00FF_FFFF) << 5);
    platform::write_u16(width, ((word2 & 0x3FF) as u16).wrapping_add(1));
    platform::write_u16(height, (((word2 >> 10) & 0x3FF) as u16).wrapping_add(1));
    platform::write_u32(field5, platform::read_u32(this + 0x14));
    platform::write_u32(field6, word0 & 3);
    platform::write_u32(field7, (word0 >> 2) & 3);
    platform::write_u8(flag, platform::read_u8(this + 0x1F) & 1);
}

/// Maps a texture-object pair onto two GX register words and emits one.
///
/// # Original
/// - Ghidra: `FUN_801c7840` at `0x801C7840` (144 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801c7840_FUN_801c7840.c`
///
/// # Arguments
/// * `index_a` - selector into the `+0x564`/`+0x584` arrays.
/// * `index_b` - selector into the `+0x108`/`+0x128` register words.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Updates the two register words with the low two ten-bit fields of `+0x564`
/// and the two `2`-bit fields of `+0x584`, emits the updated `+0x128` word to
/// the GX FIFO and clears the two-byte marker at `state + 2`.
///
/// # Safety
/// The GX state base and both indices must be valid.
///
/// # Confidence
/// high - every mask, shift and the `leading_zeros` term are literal; the field
/// roles are inferred from their masks.
pub unsafe fn fn_801c7840(index_a: u32, index_b: u32) {
    let state = gx_state_base();
    let a = state + index_a as usize * 4;
    let b = state + index_b as usize * 4;
    let v1 = platform::read_u32(a + 0x564);
    let old108 = platform::read_u32(b + 0x108);
    let lo1 = v1 & 0x3FF;
    let hi1 = (v1 >> 10) & 0x3FF;
    platform::write_u32(b + 0x108, lo1 | (old108 & 0xFFFF_0000));
    let old128 = platform::read_u32(b + 0x128);
    platform::write_u32(b + 0x128, hi1 | (old128 & 0xFFFF_0000));
    let v2 = platform::read_u32(a + 0x584);
    let t1 = (v2 & 3).wrapping_sub(1).leading_zeros();
    platform::write_u32(b + 0x108, ((t1 & 0x20) << 11) | lo1 | (old108 & 0xFFFE_0000));
    let t2 = ((v2 >> 2) & 3).wrapping_sub(1).leading_zeros();
    platform::write_u32(b + 0x128, ((t2 & 0x20) << 11) | hi1 | (old128 & 0xFFFE_0000));
    gx_fifo_write(platform::read_u32(b + 0x128));
    platform::write_u16(state + 2, 0);
}

/// Flushes the pending GX state and emits one caller word.
///
/// # Original
/// - Ghidra: `FUN_801c95e0` at `0x801C95E0` (116 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801c95e0_FUN_801c95e0.c`
///
/// # Arguments
/// * `_stream` - unused; the export never reads the first register.
/// * `word` - word emitted to the GX FIFO.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Calls [`fn_801c52f0`] when `state + 0x5FC` is non-zero, calls `0x801C56C0`
/// when `state + 0x00` is zero (the second FIFO padding writer), then writes
/// `word` to `0xCC008000`.
///
/// # Safety
/// The GX state block and the FIFO must be mapped.
///
/// # Confidence
/// high - the guards, the two calls and the single store are literal.
pub unsafe fn fn_801c95e0(_stream: u32, word: u32) {
    let state = gx_state_base();
    if platform::read_u32(state + 0x5FC) != 0 {
        fn_801c52f0();
    }
    if platform::read_u32(state) == 0 {
        // unknown: the export gives no symbol; this is the padding writer that
        // Wave 80 deliberately left untranslated.
        platform::call0(0x801C_56C0);
    }
    gx_fifo_write(word);
}

/// Transforms one point through a 3x4 matrix and scales the result.
///
/// # Original
/// - Ghidra: `FUN_801c9660` at `0x801C9660` (392 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801c9660_FUN_801c9660.c`
///
/// # Arguments
/// * `a1`, `a2`, `a3` - input point.
/// * `m` - 3x4 matrix (twelve floats).
/// * `p5` - six-float parameter block.
/// * `p6` - six-float parameter block.
/// * `p7`, `p8`, `p9` - receive the transformed x, y and z.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Writes one float to each of `p7`, `p8` and `p9`.
///
/// # Safety
/// All pointers must be valid for the sizes described.
///
/// # Confidence
/// medium - the three row dots and the branch on the SDA2 float at
/// `r2-0x4DD8` are literal; the roles of the parameter blocks are inferred
/// from their use as scale/offset pairs.
#[allow(clippy::too_many_arguments)]
pub unsafe fn fn_801c9660(
    a1: f32,
    a2: f32,
    a3: f32,
    m: usize,
    p5: usize,
    p6: usize,
    p7: usize,
    p8: usize,
    p9: usize,
) {
    let r0 = platform::read_f32(m + 0x0C)
        + platform::read_f32(m + 0x08) * a3
        + platform::read_f32(m) * a1
        + platform::read_f32(m + 0x04) * a2;
    let r1 = platform::read_f32(m + 0x1C)
        + platform::read_f32(m + 0x18) * a3
        + platform::read_f32(m + 0x10) * a1
        + platform::read_f32(m + 0x14) * a2;
    let r2 = platform::read_f32(m + 0x2C)
        + platform::read_f32(m + 0x28) * a3
        + platform::read_f32(m + 0x20) * a1
        + platform::read_f32(m + 0x24) * a2;
    let (f1, v9, v7, v8) = if sda_f32(-0x4DD8) == platform::read_f32(p5) {
        (
            sda_f32(-0x4DD4) / -r2,
            r0 * platform::read_f32(p5 + 0x04) + r2 * platform::read_f32(p5 + 0x08),
            platform::read_f32(p5 + 0x18) + r2 * platform::read_f32(p5 + 0x14),
            r1 * platform::read_f32(p5 + 0x0C) + r2 * platform::read_f32(p5 + 0x10),
        )
    } else {
        (
            sda_f32(-0x4DD4),
            platform::read_f32(p5 + 0x08) + r0 * platform::read_f32(p5 + 0x04),
            platform::read_f32(p5 + 0x18) + r2 * platform::read_f32(p5 + 0x14),
            platform::read_f32(p5 + 0x10) + r1 * platform::read_f32(p5 + 0x0C),
        )
    };
    let e0 = platform::read_f32(p6);
    let e1 = platform::read_f32(p6 + 0x04);
    let e2 = platform::read_f32(p6 + 0x08);
    let e3 = platform::read_f32(p6 + 0x0C);
    let e4 = platform::read_f32(p6 + 0x10);
    let e5 = platform::read_f32(p6 + 0x14);
    let k = sda_f32(-0x4DD0);
    platform::write_f32(p7, e2 * k + e0 + f1 * v9 * e2 * k);
    platform::write_f32(p8, e3 * k + e1 + f1 * -v8 * e3 * k);
    platform::write_f32(p9, e5 + f1 * v7 * (e5 - e4));
}

/// Stores a twelve-word colour block into the GX channel state.
///
/// # Original
/// - Ghidra: `FUN_801c9840` at `0x801C9840` (100 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801c9840_FUN_801c9840.c`
///
/// # Arguments
/// * `src` - twelve-word source block.
/// * `mode` - stored at `+0x528`; selects which pair of source words feeds
///   `+0x530`/`+0x538`.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Writes `+0x528`, `+0x52C`, `+0x534`, `+0x53C`, `+0x540`, the selected pair
/// and sets bit 27 of `+0x5FC`.
///
/// # Safety
/// `src` must address twelve readable words and the GX state block must be
/// writable.
///
/// # Confidence
/// high - every offset, the mode test and the `0x08000000` marker are literal.
pub unsafe fn fn_801c9840(src: usize, mode: u32) {
    let state = gx_state_base();
    platform::write_u32(state + 0x528, mode);
    platform::write_u32(state + 0x52C, platform::read_u32(src));
    platform::write_u32(state + 0x534, platform::read_u32(src + 0x14));
    platform::write_u32(state + 0x53C, platform::read_u32(src + 0x28));
    platform::write_u32(state + 0x540, platform::read_u32(src + 0x2C));
    if mode == 1 {
        platform::write_u32(state + 0x530, platform::read_u32(src + 0x0C));
        platform::write_u32(state + 0x538, platform::read_u32(src + 0x1C));
    } else {
        platform::write_u32(state + 0x530, platform::read_u32(src + 0x08));
        platform::write_u32(state + 0x538, platform::read_u32(src + 0x18));
    }
    let marker = platform::read_u32(state + 0x5FC);
    platform::write_u32(state + 0x5FC, marker | 0x0800_0000);
}

