    platform::write_f32(state + 0x52C, platform::read_f32(src + 0x04));
    platform::write_f32(state + 0x530, platform::read_f32(src + 0x08));
    platform::write_f32(state + 0x534, platform::read_f32(src + 0x0C));
    platform::write_f32(state + 0x538, platform::read_f32(src + 0x10));
    platform::write_f32(state + 0x53C, platform::read_f32(src + 0x14));
    platform::write_f32(state + 0x540, platform::read_f32(src + 0x18));
