/// Starts the next SYSCONF chunk and finalises the mount at the end.
///
/// # Original
/// - Ghidra: `FUN_801dbd70` at `0x801DBD70` (292 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801dbd70_FUN_801dbd70.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Advances [`SYSCONF_CHUNK`]. For chunks 0 and 1 it clears
/// [`SYSCONF_READING`] and submits the chunk through [`fn_801d9750`], retrying
/// while the submission fails. After chunk 1 it rebuilds an empty image header
/// when [`SYSCONF_RESULT`] is non-zero, clears the boot flag, calls the mount
/// completion with the result, and sets the state to `3`.
///
/// # Safety
/// The staging buffers, the boot-flag byte and the completion pointer must be
/// valid; a non-null completion takes one word.
///
/// # Confidence
/// medium - the chunk wrap, the header rebuild and the indirect call are
/// literal; the retry loop and the "last chunk" test are observed from the
/// unsigned byte compare with `1`.
pub unsafe fn fn_801dbd70() {
    loop {
        let index = platform::read_u8(SYSCONF_CHUNK).wrapping_add(1);
        platform::write_u8(SYSCONF_CHUNK, index);
        if index > 1 {
            let result = platform::read_u32(SYSCONF_RESULT);
            if result != 0 {
                let buffer = platform::read_u32(SYSCONF_BUFFER);
                platform::call3(MEMSET, buffer, 0, 0x4000);
                platform::call3(MEMCPY, buffer, SDA_SYSCONF_HEAD as u32, 4);
                platform::call3(MEMCPY, buffer + 0x3FFC, SDA_SYSCONF_TAIL as u32, 4);
                platform::write_u16(buffer as usize + 6, 8);
                platform::write_u32(SYSCONF_DONE, platform::read_u32(SYSCONF_SIZES));
            }
            platform::write_u8(SYSCONF_BOOT_FLAG, 0);
            let callback = platform::read_u32(SYSCONF_COMPLETION);
            if callback != 0 {
                platform::write_u32(SYSCONF_COMPLETION, 0);
                let func: extern "C" fn(u32) = core::mem::transmute(callback as usize);
                func(platform::read_u32(SYSCONF_RESULT));
            }
            platform::write_u8(SDA_SYSCONF_STATE, 3);
            return;
        }
        platform::write_u8(SYSCONF_READING, 0);
        let submitted = fn_801d9750(
            platform::read_u32(SYSCONF_PATHS + index as usize * 4),
            SYSCONF_FILE as u32,
            1,
            SYSCONF_NEXT_CHUNK,
            SYSCONF_CONTEXT as u32,
        );
        if submitted == 0 {
            return;
        }
    }
}

