/// [`fn_801c8250`] selects between. `// unknown:` the table role.
const GX_TEXSRC_A0: usize = 0x8034_1400;
const GX_TEXSRC_A1: usize = 0x8034_1414;

/// `0x80341428`/`0x8034143C`: the matching two four-word register tables.
/// `// unknown:` the table role.
const GX_TEXSRC_B0: usize = 0x8034_1428;
const GX_TEXSRC_B1: usize = 0x8034_143C;

/// `0x80341450`: four-word texgen-source table read by [`fn_801c8790`].
/// `// unknown:` the entry values; index `0xFF` is special-cased to seven.
const GX_TEXGEN_SOURCE_TABLE: usize = 0x8034_1450;

/// `0x803904D0`: nine-word draw-frame block filled by [`fn_801c9470`].
const GX_FRAME_BLOCK: usize = 0x8039_04D0;
/// `0x80390B50`: second draw-token block passed to `0x801C3440`.
const GX_TOKEN_BLOCK_B: usize = 0x8039_0B50;
/// `0x80390550`: 0x600-byte shadow copy of the GX state block.
const GX_STATE_SHADOW: usize = 0x8039_0550;
/// `0x801C2E70`: token-block submission (untranslated; called by address).
const GX_TOKEN_SUBMIT: usize = 0x801C_2E70;
