const GX_TOKEN_RELEASE: usize = 0x801C_34D0;

/// Emits one float to the GX write-gather FIFO.
///
/// # Safety
/// `0xCC008000` must be the mapped GX FIFO.
#[inline]
unsafe fn gx_fifo_write_f32(value: f32) {
    gx_fifo_write(value.to_bits());
}

/// Reads one byte from an `r13`-relative table entry `index`.
///
/// # Safety
/// `SDA_BASE + offset + index` must be a readable byte.
#[inline]
unsafe fn sda_table_byte(offset: isize, index: u32) -> u8 {
    platform::read_u8((SDA_BASE as isize + offset + index as isize) as usize)
}

/// Calls the SDK tangent helper.
///
/// # Safety
/// `0x802E8590` must be the entry point of an `f64(f64)` routine.
#[inline]
unsafe fn fp_tan(value: f64) -> f64 {
    let f: extern "C" fn(f64) -> f64 = core::mem::transmute(FP_TAN_F64);
    f(value)
}

/// Calls the SDK `double` to `u32` conversion helper.
///
/// # Safety
/// `0x802DCC4C` must be the entry point of a `u32(f64)` routine.
#[inline]
unsafe fn fp_to_u32(value: f64) -> u32 {
    let f: extern "C" fn(f64) -> u32 = core::mem::transmute(FP_TO_U32);
    f(value)
}

