    platform::write_f32(out + 0x14, 1.0 - scale * (x * x + z * z));
    platform::write_f32(out + 0x18, scale * (y * z - x * w));
    platform::write_f32(out + 0x1C, 0.0);
    platform::write_f32(out + 0x20, scale * (x * z - y * w));
