    let old1 = platform::read_u32(obj + 4);
    let old2 = platform::read_u32(obj + 8);
    let old3 = platform::read_u32(obj + 0x0C);
    let old_other0 = platform::read_u32(other);
    let old_other1 = platform::read_u32(other + 4);
