/// * `state` - one-byte state slot set to `1`/`2` by the synchronous core.
/// * `file` - asynchronous file object (`+0x30` out-word, `+0x34` path buffer,
///   `+0x88` state pointer slot).
/// * `is_async` - `0` selects the synchronous core.
/// * `allow_shared2` - when `0`, a `/shared2/...` path deeper than the prefix
///   is rejected with `0xFFFFFF9A`.
///
/// # Returns
/// `0` on the synchronous success paths, `-0x65` for an empty path, `-0x66`
/// for a rejected path, else the open core's result.
///
/// # Side effects
/// Builds the full path into a local buffer (sync) or into `file + 0x34`
/// (async), strips a trailing slash, calls `0x80226940` or `0x80226AA0`, and on
/// success writes the state byte through the `state` pointer.
///
/// # Safety
/// `path` readable; `state` one writable byte; `file` writable in the async
/// branch.
///
/// # Confidence
/// medium - both path branches, the trailing-slash strip, the prefix test and
/// the two core calls are literal; the two prologue words are recovered as
/// `path`/`state`, and the "open" role is `// inferred:` from the state byte
/// convention shared with [`fn_801daf10`].
pub unsafe fn fn_801dab90(
    path: u32,
    state: u32,
    file: u32,
    is_async: u32,
    allow_shared2: u32,
) -> u32 {
    if platform::call1(STRLEN, path) == 0 {
        return 0xFFFF_FF9B;
    }
    if is_async == 0 {
        let mut buffer = [0u8; 0x40];
        let length = platform::call1(STRLEN, path);
        if length == 0 {
            platform::call2(STRCPY, buffer.as_mut_ptr() as u32, SDA_ISFS_DEFAULT_PATH as u32);
        } else if platform::read_u8(path as usize) == b'/' {
            platform::call2(STRCPY, buffer.as_mut_ptr() as u32, path);
            let length = platform::call1(STRLEN, buffer.as_ptr() as u32) as usize;
            if length != 0
                && platform::read_u8(buffer.as_ptr() as usize + length - 1) == b'/'
                && length != 1
            {
                platform::write_u8(buffer.as_ptr() as usize + length - 1, 0);
            }
        } else {
            platform::call3(
                ISFS_PATH_RESOLVE,
                buffer.as_mut_ptr() as u32,
                ISFS_PATH_FORMAT as u32,
                path,
            );
        }
        if allow_shared2 == 0 {
            let deeper = platform::read_u8(buffer.as_ptr() as usize + 9) != 0;
            if platform::call3(
                STRNCMP,
                buffer.as_ptr() as u32,
                ISFS_SHARED2_SLASH as u32,
                9,
            ) == 0
                && deeper
            {
                return 0xFFFF_FF9A;
            }
        }
        let mut out_word = 0u32;
        let code = platform::call3(
            ISFS_OP_26940,
            buffer.as_ptr() as u32,
            0,
            &mut out_word as *mut u32 as u32,
        );
        if code == 0 || code == 0xFFFF_FF9A {
            platform::write_u8(state as usize, 2);
            return 0;
        }
        if code == 0xFFFF_FF9B {
            platform::write_u8(state as usize, 1);
            return 0;
        }
        code
    } else {
        let path_buffer = (file + 0x34) as usize;
        let length = platform::call1(STRLEN, path);
        if length == 0 {
            platform::call2(STRCPY, path_buffer as u32, SDA_ISFS_DEFAULT_PATH as u32);
        } else if platform::read_u8(path as usize) == b'/' {
            platform::call2(STRCPY, path_buffer as u32, path);
            let length = platform::call1(STRLEN, path_buffer as u32) as usize;
            if length != 0
                && platform::read_u8(path_buffer + length - 1) == b'/'
                && length != 1
            {
                platform::write_u8(path_buffer + length - 1, 0);
            }
        } else {
            platform::call3(ISFS_PATH_RESOLVE, path_buffer as u32, ISFS_PATH_FORMAT as u32, path);
        }
        if allow_shared2 == 0 {
            let deeper = platform::read_u8(path_buffer + 9) != 0;
            if platform::call3(STRNCMP, path_buffer as u32, ISFS_SHARED2_SLASH as u32, 9) == 0
                && deeper
            {
                return 0xFFFF_FF9A;
            }
        }
        platform::write_u32(file as usize + 0x88, state);
        platform::call5(
            ISFS_OP_26AA0,
            path_buffer as u32,
            0,
            file + 0x30,
            ISFS_OPEN_COMPLETION,
            file,
        )
    }
}

// ---------------------------------------------------------------------------
// Wave 100: 3x4 matrix / quaternion maths, GX draw-state helpers and bring-up
// ---------------------------------------------------------------------------
//
// The `0x801C0000` bucket still held 37 untranslated addresses. This pass takes
// 24 of them in four groups. None of it is disc code: like the Wave 40/46/56/
// 67/80/90/95 slices above, it lives here only because this file is the single
// writable file assigned to the bucket.
//
// - `0x801C0540`-`0x801C1850` (6 bodies) - the rest of the SDK matrix library:
//   the 3x4 concatenation [`fn_801c0540`], the affine inverse
//   [`fn_801c07a0`], the 3x3 inverse [`fn_801c08a0`], the axis-angle builder
//   [`fn_801c0aa0`], the quaternion extraction [`fn_801c1680`] and the
//   quaternion slerp [`fn_801c1850`].
// - `0x801C1B10`-`0x801C99C0` (10 bodies) - GX draw state and FIFO payloads:
//   the retrace latch [`fn_801c1b10`], the channel-field writer
//   [`fn_801c1c80`], the draw-token service pair [`fn_801c2b80`]/
//   [`fn_801c2e70`] with its CP sibling [`fn_801c3050`], the TEV-stage
//   refresh [`fn_801c78d0`], the literal `0xE8` emitter [`fn_801c8cb0`] and
//   the three float emitters [`fn_801c97f0`], [`fn_801c99c0`],
//   [`fn_801c9940`].
// - `0x801C19F0`-`0x801C6FA0` (4 bodies) - texture-object and lighting
//   helpers: the texture block selector [`fn_801c19f0`], the post-init store
//   [`fn_801c6fa0`], the fog parameter selector [`fn_801c6470`] and the
//   normalised-direction writer [`fn_801c6760`].
// - `0x801C0020`-`0x801C5BC0` (4 bodies) - the video-mode command sequence
//   [`fn_801c0020`], the GX bring-up [`fn_801c1db0`], the depth-value builder
//   [`fn_801c8b50`] and the 9-bit scale search [`fn_801c5bc0`].
//
// **GQR0 note.** As in the Wave 90 and Wave 95 sections above, the paired-single
// access arms (`4`/`5`/`6`/`7` of GQR0) are not reproduced; the bodies below are
// the plain `f32` arm and say so in `# Confidence`.

/// `0x802E84C4`: single-precision sine. `// inferred:` [`fn_801c1850`] feeds it
/// both half-angles and divides the results.
const FP_SIN_F32: usize = 0x802E_84C4;

/// `0x802E7FBC`: single-precision cosine. `// inferred:` the fog selector
/// [`fn_801c6470`] passes it an angle and uses the result as `cos`.
const FP_COS_F32: usize = 0x802E_7FBC;

/// `0x802E46A0`: single-precision arc cosine. `// inferred:` [`fn_801c1850`]
/// passes it a clamped quaternion dot product and treats the result as an angle.
const FP_ACOS_F32: usize = 0x802E_46A0;

/// `0x804295A0`/`0x804295A4`: the two `.sdata2` words that scale the translation
/// column in [`fn_801c0540`]. The `+0x08`/`+0x0C` row terms of that body prove
/// they are zero and one; the body reads them instead of assuming it.
const MTX_CONCAT_C0: usize = 0x8042_95A0;
const MTX_CONCAT_C1: usize = 0x8042_95A4;

/// `r2 - 0x4F04`: `f32` zero used by the quaternion and slerp bodies.
const MTXQ_ZERO: isize = -0x4F04;
/// `r2 - 0x4F08`: `f32` one used by the quaternion and slerp bodies.
const MTXQ_ONE: isize = -0x4F08;
/// `r2 - 0x4F00`: `f32` 0.5 used by the quaternion builder.
const MTXQ_HALF: isize = -0x4F00;
/// `r2 - 0x4EFC`: dot-product threshold above which [`fn_801c1850`] blends
/// linearly instead of taking the arc cosine. `// inferred:` a value very close
/// to one.
const MTXQ_DOT_LIMIT: isize = -0x4EFC;

/// Calls the SDK single-precision sine.
///
/// # Safety
/// `0x802E84C4` must be the entry point of an `f32(f32)` routine.
#[inline]
unsafe fn fp_sin(value: f32) -> f32 {
    let f: extern "C" fn(f32) -> f32 = core::mem::transmute(FP_SIN_F32);
    f(value)
}

/// Calls the SDK single-precision cosine.
///
/// # Safety
/// `0x802E7FBC` must be the entry point of an `f32(f32)` routine.
#[inline]
unsafe fn fp_cos(value: f32) -> f32 {
    let f: extern "C" fn(f32) -> f32 = core::mem::transmute(FP_COS_F32);
    f(value)
}

/// Calls the SDK single-precision arc cosine.
///
/// # Safety
/// `0x802E46A0` must be the entry point of an `f32(f32)` routine.
#[inline]
unsafe fn fp_acos(value: f32) -> f32 {
    let f: extern "C" fn(f32) -> f32 = core::mem::transmute(FP_ACOS_F32);
    f(value)
}

/// Multiplies two 3x4 matrices.
///
/// # Original
/// - Ghidra: `FUN_801c0540` at `0x801C0540` (204 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801c0540_FUN_801c0540.c`
///
/// # Arguments
/// - `a`: left matrix, twelve floats laid out as three rows of four; the fourth
///   word of each row is the translation.
/// - `b`: right matrix, same layout.
/// - `out`: destination, same layout.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Writes the twelve floats of `a * b`. The export stores the pairs in the order
/// `(0,1)`, `(4,5)`, `(2,3)`, `(6,7)`, `(8,9)`, `(10,11)`; the final memory image
/// is the ordinary row-major product. `0x804295A0`/`0x804295A4` scale `a`'s
/// translation in the `+0x08`/`+0x0C` columns.
///
/// # Safety
/// `a` and `b` must address 48 readable bytes and `out` 48 writable bytes.
///
/// # Confidence
/// medium - every dot product and the two tail constants are literal; the
/// paired-single quantised arms are not reproduced (see the GQR0 note above) and
/// the chained products are evaluated in `f32`, `// inferred:` from `ps_madd`.
pub unsafe fn fn_801c0540(a: usize, b: usize, out: usize) {
    let c0 = platform::read_f32(MTX_CONCAT_C0);
    let c1 = platform::read_f32(MTX_CONCAT_C1);
    let mut row = 0usize;
    while row < 3 {
        let src = a + row * 0x10;
        let a0 = platform::read_f32(src);
        let a1 = platform::read_f32(src + 0x04);
        let a2 = platform::read_f32(src + 0x08);
        let a3 = platform::read_f32(src + 0x0C);
        let dst = out + row * 0x10;
        // observed: the products run backwards (column 2 first), as the export's
        // `dVar17 * dVar8 + dVar15 * dVar22 + dVar13 * dVar7` shows.
        platform::write_f32(
            dst,
            a2 * platform::read_f32(b + 0x20)
                + a1 * platform::read_f32(b + 0x10)
                + a0 * platform::read_f32(b),
        );
        platform::write_f32(
            dst + 0x04,
            a2 * platform::read_f32(b + 0x24)
                + a1 * platform::read_f32(b + 0x14)
                + a0 * platform::read_f32(b + 0x04),
        );
        platform::write_f32(
            dst + 0x08,
            c0 * a3 + a2 * platform::read_f32(b + 0x28)
                + a1 * platform::read_f32(b + 0x18)
                + a0 * platform::read_f32(b + 0x08),
        );
        platform::write_f32(
            dst + 0x0C,
            c1 * a3 + a2 * platform::read_f32(b + 0x2C)
                + a1 * platform::read_f32(b + 0x1C)
                + a0 * platform::read_f32(b + 0x0C),
        );
        row += 1;
    }
}

/// Inverts a 3x4 affine matrix.
///
/// # Original
/// - Ghidra: `FUN_801c07a0` at `0x801C07A0` (248 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801c07a0_FUN_801c07a0.c`
///
/// # Arguments
/// - `src`: source matrix, twelve floats (three rows of four).
/// - `dst`: destination matrix, same layout.
///
/// # Returns
/// `1` when the 3x3 part is invertible, `0` when its determinant is zero (the
/// export compares the determinant against `dVar19 - dVar19`, i.e. zero).
///
/// # Side effects
/// On success writes all twelve floats: the inverse of the upper 3x3 and
/// `-(R^-1 * t)` in the translation column. The reciprocal gets one Newton step,
/// `inv = 2*i - i*i*det`, exactly as the export spells it.
///
/// # Safety
/// `src` must address 48 readable bytes and `dst` 48 writable bytes.
///
/// # Confidence
/// medium - the cofactors, determinant and Newton step are literal; the
/// arithmetic is evaluated in `f32` (`// inferred:` from the paired singles).
pub unsafe fn fn_801c07a0(src: usize, dst: usize) -> u32 {
    let a00 = platform::read_f32(src);
    let a01 = platform::read_f32(src + 0x04);
    let a02 = platform::read_f32(src + 0x08);
    let tx = platform::read_f32(src + 0x0C);
    let a10 = platform::read_f32(src + 0x10);
    let a11 = platform::read_f32(src + 0x14);
    let a12 = platform::read_f32(src + 0x18);
    let ty = platform::read_f32(src + 0x1C);
    let a20 = platform::read_f32(src + 0x20);
    let a21 = platform::read_f32(src + 0x24);
    let a22 = platform::read_f32(src + 0x28);
    let tz = platform::read_f32(src + 0x2C);

    // observed: cofactors of column 0 (c20/c10/c00) build the determinant.
    let c20 = a01 * a12 - a11 * a02;
    let c00 = a11 * a22 - a21 * a12;
    let c10 = a21 * a02 - a01 * a22;
    let det = a20 * c20 + a10 * c10 + a00 * c00;
    if det == 0.0 {
        return 0;
    }
    let i0 = 1.0f32 / det;
    // observed: one Newton step on the reciprocal.
    let inv = -(i0 * det * i0 - (i0 + i0));
    let c01 = a12 * a20 - a10 * a22;
    let c02 = a10 * a21 - a11 * a20;
    let c11 = a00 * a22 - a02 * a20;
    let c12 = a01 * a20 - a00 * a21;
    let c21 = a02 * a10 - a00 * a12;
    let c22 = a00 * a11 - a01 * a10;

    let m00 = c00 * inv;
    let m01 = c10 * inv;
    let m02 = c20 * inv;
    let m10 = c01 * inv;
    let m11 = c11 * inv;
    let m12 = c21 * inv;
    let m20 = c02 * inv;
    let m21 = c12 * inv;
    let m22 = c22 * inv;

    platform::write_f32(dst, m00);
    platform::write_f32(dst + 0x04, m01);
    platform::write_f32(dst + 0x08, m02);
    // observed: -(m02*tz + m01*ty + m00*tx), in that term order.
    platform::write_f32(dst + 0x0C, -(m02 * tz + m01 * ty + m00 * tx));
    platform::write_f32(dst + 0x10, m10);
    platform::write_f32(dst + 0x14, m11);
    platform::write_f32(dst + 0x18, m12);
    platform::write_f32(dst + 0x1C, -(m12 * tz + m11 * ty + m10 * tx));
    platform::write_f32(dst + 0x20, m20);
    platform::write_f32(dst + 0x24, m21);
    platform::write_f32(dst + 0x28, m22);
    platform::write_f32(dst + 0x2C, -(m22 * tz + m21 * ty + m20 * tx));
    1
}

/// Inverts the 3x3 part of a 3x4 matrix and clears the translation column.
///
/// # Original
/// - Ghidra: `FUN_801c08a0` at `0x801C08A0` (200 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801c08a0_FUN_801c08a0.c`
///
/// # Arguments
/// - `src`: source matrix, twelve floats (three rows of four).
/// - `dst`: destination matrix, same layout.
///
/// # Returns
/// `1` when the 3x3 part is invertible, `0` otherwise.
///
/// # Side-effects
/// Writes `dst[3]`, `dst[7]` and `dst[11]` as zero (the export stores the
/// degenerate `dVar14 = dVar19 - dVar19` placeholder) and the nine inverse
/// terms. The reciprocal gets the same `2*i - i*i*det` Newton step as
/// [`fn_801c07a0`].
///
/// # Safety
/// `src` must address 48 readable bytes and `dst` 48 writable bytes.
///
/// # Confidence
/// medium - the nine cofactors and the Newton step are literal; the arithmetic
/// is evaluated in `f32` (`// inferred:` from the paired singles).
pub unsafe fn fn_801c08a0(src: usize, dst: usize) -> u32 {
    let a00 = platform::read_f32(src);
    let a01 = platform::read_f32(src + 0x04);
    let a02 = platform::read_f32(src + 0x08);
    let a10 = platform::read_f32(src + 0x10);
    let a11 = platform::read_f32(src + 0x14);
    let a12 = platform::read_f32(src + 0x18);
    let a20 = platform::read_f32(src + 0x20);
    let a21 = platform::read_f32(src + 0x24);
    let a22 = platform::read_f32(src + 0x28);

    let c20 = a01 * a12 - a11 * a02;
    let c00 = a11 * a22 - a21 * a12;
    let c10 = a21 * a02 - a01 * a22;
    let det = a20 * c20 + a10 * c10 + a00 * c00;
    if det == 0.0 {
        return 0;
    }
    let i0 = 1.0f32 / det;
    let zero = 0.0f32;
    platform::write_f32(dst + 0x0C, zero);
    platform::write_f32(dst + 0x1C, zero);
    platform::write_f32(dst + 0x2C, zero);
    let inv = -(i0 * det * i0 - (i0 + i0));
    let c01 = a12 * a20 - a10 * a22;
    let c02 = a10 * a21 - a11 * a20;
    let c11 = a00 * a22 - a02 * a20;
    let c12 = a01 * a20 - a00 * a21;
    let c21 = a02 * a10 - a00 * a12;
    let c22 = a00 * a11 - a01 * a10;

    platform::write_f32(dst, c00 * inv);
    platform::write_f32(dst + 0x04, c01 * inv);
    platform::write_f32(dst + 0x10, c10 * inv);
    platform::write_f32(dst + 0x14, c11 * inv);
    platform::write_f32(dst + 0x20, c20 * inv);
    platform::write_f32(dst + 0x24, c21 * inv);
    platform::write_f32(dst + 0x08, c02 * inv);
    platform::write_f32(dst + 0x18, c12 * inv);
    platform::write_f32(dst + 0x28, c22 * inv);
    1
}

/// Extracts a quaternion from a rotation matrix.
///
/// # Original
/// - Ghidra: `FUN_801c1680` at `0x801C1680` (460 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801c1680_FUN_801c1680.c`
///
/// # Arguments
/// - `out`: destination quaternion, four floats `(x, y, z, w)`.
/// - `m`: source rotation matrix; the body reads it with four-float rows
///   (`m[i][j]` is `m + i*0x10 + j*0x04`), so it is a 4x4 upper-left block.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Writes the four quaternion floats. The trace branch picks the largest
/// diagonal element through the three-word table at `0x802F6AD0` (read here,
/// `// inferred:` `{1, 2, 0}` - the `i -> j -> k` rotation of the classic
/// extraction) and takes one square root; the flat branch takes one as well.
///
/// # Safety
/// `out` must address 16 writable bytes and `m` 44 readable bytes.
///
/// # Confidence
/// medium - the branch guards, the three square roots and every term are
/// literal; the `0x802F6AD0` table contents and the half/one/zero SDA roles are
/// inferred from the formulas.
pub unsafe fn fn_801c1680(out: usize, m: usize) {
    let zero = sda_f32(MTXQ_ZERO);
    let one = sda_f32(MTXQ_ONE);
    let half = sda_f32(MTXQ_HALF);
    let m00 = platform::read_f32(m);
    let m11 = platform::read_f32(m + 0x14);
    let m22 = platform::read_f32(m + 0x28);
    let trace = m22 + m00 + m11;
    if trace <= zero {
        let mut i = if m00 < m11 { 1usize } else { 0usize };
        if platform::read_f32(m + i * 0x14) < m22 {
            i = 2;
        }
        // observed: the two indices come from the `0x802F6AD0` word table.
        let table = [
            platform::read_u32(0x802F_6AD0) as usize,
            platform::read_u32(0x802F_6AD4) as usize,
            platform::read_u32(0x802F_6AD8) as usize,
        ];
        let j = table[i];
        let k = table[j];
        let diag = platform::read_f32(m + i * 0x14)
            - (platform::read_f32(m + j * 0x14) + platform::read_f32(m + k * 0x14));
        let root = mtx_sqrt((one + diag) as f64) as f32;
        let mut q = [0.0f32; 3];
        q[i] = half * root;
        let scale = if zero != root { half / root } else { root };
        q[j] = scale
            * (platform::read_f32(m + i * 0x10 + j * 0x04)
                + platform::read_f32(m + j * 0x10 + i * 0x04));
        q[k] = scale
            * (platform::read_f32(m + i * 0x10 + k * 0x04)
                + platform::read_f32(m + k * 0x10 + i * 0x04));
        platform::write_f32(
            out + 0x0C,
            scale * (platform::read_f32(m + k * 0x10 + j * 0x04)
                - platform::read_f32(m + j * 0x10 + k * 0x04)),
        );
        platform::write_f32(out, q[0]);
        platform::write_f32(out + 0x04, q[1]);
        platform::write_f32(out + 0x08, q[2]);
    } else {
        let root = mtx_sqrt((one + trace) as f64) as f32;
        let scale = half / root;
        platform::write_f32(out + 0x0C, half * root);
        platform::write_f32(
            out,
            scale * (platform::read_f32(m + 0x24) - platform::read_f32(m + 0x18)),
        );
        platform::write_f32(
            out + 0x04,
            scale * (platform::read_f32(m + 0x08) - platform::read_f32(m + 0x20)),
        );
        platform::write_f32(
            out + 0x08,
            scale * (platform::read_f32(m + 0x10) - platform::read_f32(m + 0x04)),
        );
    }
}

/// Spherical linear interpolation between two quaternions.
///
/// # Original
/// - Ghidra: `FUN_801c1850` at `0x801C1850` (412 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801c1850_FUN_801c1850.c`
///
/// # Arguments
/// - `t`: interpolation factor, clamped by the caller.
/// - `a`, `b`: the two quaternions, four floats each.
/// - `out`: destination quaternion.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Writes the four floats of `s1*a + s2*b` (with `b` negated when the dot
/// product is negative). When `|dot|` exceeds `r2-0x4EFC` the body blends
/// linearly (`s1 = 1-t`, `s2 = +-t`); otherwise it takes `acos(dot)` and
/// divides the two `sin` results.
///
/// # Safety
/// `a`, `b` and `out` must each address 16 readable/writable bytes.
///
/// # Confidence
/// medium - the branches, the three trig calls and every term are literal; the
/// SDA roles (one, zero, threshold) are inferred from the formulas and the
/// arithmetic is the `f32` arm.
pub unsafe fn fn_801c1850(t: f32, a: usize, b: usize, out: usize) {
    let one = sda_f32(MTXQ_ONE);
    let zero = sda_f32(MTXQ_ZERO);
    let limit = sda_f32(MTXQ_DOT_LIMIT);
    let a0 = platform::read_f32(a);
    let a1 = platform::read_f32(a + 0x04);
    let a2 = platform::read_f32(a + 0x08);
    let a3 = platform::read_f32(a + 0x0C);
    let b0 = platform::read_f32(b);
    let b1 = platform::read_f32(b + 0x04);
    let b2 = platform::read_f32(b + 0x08);
    let b3 = platform::read_f32(b + 0x0C);

    // observed: dot = a3*b3 + a2*b2 + a0*b0 + a1*b1.
    let mut dot = a3 * b3 + a2 * b2 + a0 * b0 + a1 * b1;
    let mut w = one;
    if dot < zero {
        dot = -dot;
        w = -w;
    }
    let s1;
    if dot > limit {
        w *= t;
        s1 = one - t;
    } else {
        let theta = fp_acos(dot);
        let sin_theta = fp_sin(theta);
        s1 = fp_sin((one - t) * theta) / sin_theta;
        w *= fp_sin(t * theta) / sin_theta;
    }
    platform::write_f32(out, s1 * a0 + w * b0);
    platform::write_f32(out + 0x04, s1 * a1 + w * b1);
    platform::write_f32(out + 0x08, s1 * a2 + w * b2);
    platform::write_f32(out + 0x0C, s1 * a3 + w * b3);
}

/// Builds a 3x4 rotation matrix from a rotation axis and its sine/cosine.
///
/// # Original
/// - Ghidra: `FUN_801c0aa0` at `0x801C0AA0` (176 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801c0aa0_FUN_801c0aa0.c`
///
/// # Arguments
/// - `s`, `c`: sine and cosine of the rotation angle. The body forms `1-c`
///   itself as `2*0.5 - c`.
/// - `out`: destination, twelve floats (three rows of four; the fourth word of
///   each row is written as zero).
/// - `axis`: three floats, the rotation axis; normalised by the body.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Writes the twelve floats of the standard axis-angle rotation matrix. The axis
/// normalisation is `1/sqrt(len2)` followed by one reciprocal-square-root Newton
/// step, `(3 - inv*inv*len2) * inv * 0.5`.
///
/// # Safety
/// `axis` must address 12 readable bytes and `out` 48 writable bytes.
///
/// # Confidence
/// medium - every product and store is literal and the matrix layout is proven
/// by the three zeros; the `0x4F48`/`0x4F44` SDA words are read as `0.5`/`3.0`
/// (`// inferred:` from the Newton step and `1-c`).
pub unsafe fn fn_801c0aa0(s: f32, c: f32, out: usize, axis: usize) {
    let half = sda_f32(-0x4F48);
    let three = sda_f32(-0x4F44);
    let ax = platform::read_f32(axis);
    let ay = platform::read_f32(axis + 0x04);
    let az = platform::read_f32(axis + 0x08);
    // observed: len2 = z*z + x*x + y*y, then 1.0 / SQRT(len2).
    let len2 = az * az + ax * ax + ay * ay;
    let inv0 = 1.0f32 / mtx_sqrt(len2 as f64) as f32;
    let inv = -((inv0 * inv0) * len2 - three) * (inv0 * half);
    let x = ax * inv;
    let y = ay * inv;
    let z = az * inv;
    let t = (half + half) - c;
    let xt = x * t;
    let yt = y * t;
    let zt = z * t;
    let xy = xt * y;
    let yz = yt * z;
    let xz = xt * z;
    let zero = half - half;

    platform::write_f32(out, xt * x + c);
    platform::write_f32(out + 0x04, xy - z * s);
    platform::write_f32(out + 0x08, xz + y * s);
    platform::write_f32(out + 0x0C, zero);
    platform::write_f32(out + 0x10, z * s + xy);
    platform::write_f32(out + 0x14, yt * y + c);
    platform::write_f32(out + 0x18, yz - x * s);
    platform::write_f32(out + 0x1C, zero);
    platform::write_f32(out + 0x20, xz - y * s);
    platform::write_f32(out + 0x24, x * s + yz);
    platform::write_f32(out + 0x28, zt * z + c);
    platform::write_f32(out + 0x2C, zero);
}

/// Sets the "dirty/ready" bits of the three GX channel-control word pairs.
///
/// # Original
/// - Ghidra: `FUN_801c1c80` at `0x801C1C80` (304 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801c1c80_FUN_801c1c80.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Two passes over four-word groups: every word of the group at `+0x1C` (and
/// then at `+0x2C`) gets `0x40000000`, every word of the group at `+0x3C` (and
/// then at `+0x4C`) gets `0x80000000`. Finally the `0x5800000F` XF load header
/// (count `0xF`) goes to the FIFO.
///
/// # Safety
/// The SDA2 state slot must hold the GX state block and `0xCC008000` must be
/// the mapped FIFO.
///
/// # Confidence
/// high - the loop count, the four mask/or pairs and the final literal word are
/// all in the export.
pub unsafe fn fn_801c1c80() {
    let state = gx_state_base();
    let mut block = state + 0x1C;
    let mut remaining = 2u32;
    loop {
        platform::write_u32(block, platform::read_u32(block) | 0x4000_0000);
        platform::write_u32(block + 0x20, platform::read_u32(block + 0x20) | 0x8000_0000);
        platform::write_u32(block + 0x04, platform::read_u32(block + 0x04) | 0x4000_0000);
        platform::write_u32(block + 0x24, platform::read_u32(block + 0x24) | 0x8000_0000);
        platform::write_u32(block + 0x08, platform::read_u32(block + 0x08) | 0x4000_0000);
        platform::write_u32(block + 0x28, platform::read_u32(block + 0x28) | 0x8000_0000);
        platform::write_u32(block + 0x0C, platform::read_u32(block + 0x0C) | 0x4000_0000);
        platform::write_u32(block + 0x2C, platform::read_u32(block + 0x2C) | 0x8000_0000);
        block += 0x10;
        remaining -= 1;
        if remaining == 0 {
            break;
        }
    }
    platform::write_u32(GX_FIFO, 0x5800_000F);
}

