/// Re-emits the GX texture/indirect stages whose state bits are not yet dirty.
///
/// # Original
/// - Ghidra: `FUN_801c78d0` at `0x801C78D0` (356 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801c78d0_FUN_801c78d0.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// When the "stage count valid" word at `+0x5E4` is not `0xFF`, walks up to four
/// texture stages (count in bits 16-18 of `+0x254`) and up to sixteen indirect
/// stages (count in bits 10-13) and calls [`fn_801c7840`] for each stage whose
/// dirty bit is clear. The two bitmaps are `+0x5E4` (one bit per resource) and
/// `+0x5E8` (`1 << stage`).
///
/// # Safety
/// The SDA2 state slot must hold the GX state block.
///
/// # Confidence
/// medium - the two counts, the four `+0x170` nibble extractions and the two
/// dirty tests are literal; the field names are inferred from their width.
pub unsafe fn fn_801c78d0() {
    let state = gx_state_base();
    let dirty = platform::read_u32(state + 0x5E4);
    if dirty == 0xFF {
        return;
    }
    let stages = platform::read_u32(state + 0x254);
    let texture_stages = (stages >> 0x10) & 7;
    let texcoords = platform::read_u32(state + 0x170);
    let mut stage = 0u32;
    while stage < texture_stages {
        let (source, selector) = match stage {
            0 => (texcoords & 7, (texcoords >> 3) & 7),
            1 => ((texcoords >> 6) & 7, (texcoords >> 9) & 7),
            2 => ((texcoords >> 0x0C) & 7, (texcoords >> 0x0F) & 7),
            3 => ((texcoords >> 0x12) & 7, (texcoords >> 0x15) & 7),
            // observed: never reached, the count is at most four.
            _ => (0, 0),
        };
        if (dirty & (1 << selector)) == 0 {
            fn_801c7840(source, selector);
        }
        stage += 1;
    }
    let indirect = (stages >> 10) & 0xF;
    let enabled = platform::read_u32(state + 0x5E8);
    let mut index = 0u32;
    while index < indirect + 1 {
        let pair = index >> 1;
        let word = platform::read_u32(state + 0x5A4 + index as usize * 4) & 0xFFFF_FEFF;
        let source = platform::read_u32(state + 0x150 + pair as usize * 4);
        let field = if (index & 1) == 0 {
            (source >> 3) & 7
        } else {
            (source >> 0x0F) & 7
        };
        if word != 0xFF && (dirty & (1 << field)) == 0 && (enabled & (1 << index)) != 0 {
            fn_801c7840(word, field);
        }
        index += 1;
    }
}

