/// Shared success tail of [`fn_801dce90`] states `8` and `9`.
///
/// # Safety
/// The SYSCONF globals and callback must be valid.
#[inline]
unsafe fn ysc_conf_report() {
    if platform::read_u32(SYSCONF_STATUS) != 0 {
        platform::write_u8(SETTINGS_DIRTY, 1);
    }
    let done = platform::read_u32(SYSCONF_CALLBACK);
    if done != 0 {
        platform::write_u32(SYSCONF_CALLBACK, 0);
        platform::call1(done as usize, platform::read_u32(SYSCONF_STATUS));
        if platform::read_u32(SYSCONF_LOCK) != 0 {
            platform::call1(SYSCONF_RELEASE_OBJ, SYSCONF_LOCK as u32);
        }
    }
    platform::write_u8(
        SDA_SYSCONF_STATE,
        platform::read_u32(SYSCONF_STATUS) as u8,
    );
}

/// `0x80226740`: creates one flash directory (`path, 0, 3, 3, 3`).
const ISFS_CREATE_DIR: usize = 0x8022_6740;

/// `0x80343598`: `"/tmp/sys"`, the scratch directory used by the save path.
const TMP_PATH: u32 = 0x8034_3598;

/// `r13 - 0x6000`: format string that joins the scratch directory and a file
/// base name. `// inferred:` it behaves like `"%s/%s"`, because it receives
/// exactly the two pointers.
const SDA_ISFS_TMP_JOIN: usize = SDA_BASE - 0x6000;

/// `r13 - 0x6008`: format string that appends the sequence counter to the
/// scratch directory name. `// unknown:` the literal text.
const SDA_ISFS_TMP_DIR_FORMAT: usize = SDA_BASE - 0x6008;

/// `0x803435A4`: `"%s.%08x.%s"`-shaped name format used when the caller asks for
/// a numbered copy. `// inferred:` from the three operands it receives.
const ISFS_TMP_NAME_FORMAT: u32 = 0x8034_35A4;

/// `r13 - 0x4C48`: wrap-around counter embedded into the scratch file name.
/// `// inferred:` incremented under the interrupt lock just before the format.
const SDA_ISFS_TMP_SEQ: usize = SDA_BASE - 0x4C48;

/// Saves a file by copying it through `/tmp/sys`, or re-opens it in place.
///
/// # Original
/// - Ghidra: `FUN_801d9950` at `0x801D9950` (948 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801d9950_FUN_801d9950.c`
///
/// # Arguments
/// * `prefix` - path handed to [`fn_801da6e0`] to fill `context + 0x08`.
/// * `context` - ISFS file context: `+0x00` destination descriptor, `+0x04`
///   source descriptor, `+0x08` source path, `+0x48` destination path,
///   `+0x88` mode byte, `+0x89` stage byte, `+0x8A` result stage byte.
/// * `mode` - `1` opens in place, `2` and `3` save through the scratch copy.
/// * `buffer` - staging buffer for the copy.
/// * `length` - buffer size; must have a non-zero low 14 bits.
///
/// # Returns
/// `0` on success, `0xFFFFFF80` when ISFS is not ready, `0xFFFFFFF8` for a bad
/// length or mode, `0xFFFFFFFF` when the path does not resolve, otherwise the
/// value returned by the error mapper [`fn_801da570`].
///
/// # Side effects
/// Reads the directory attributes and (for modes 2/3) recreates them with
/// [`ISFS_OP_273A0`], opens the source descriptor, builds a scratch name,
/// copies the data with `0x802278A0`/`0x80227970` and sets the file mode.
///
/// # Safety
/// `context` must be a live ISFS file context, `buffer` must hold `length` bytes
/// and `prefix` must be NUL-terminated.
///
/// # Confidence
/// medium - the guard ladder, the attribute round-trip, the scratch name and the
/// copy loop are literal; the `0x802DCD6C` prologue pair is read as
/// `(prefix, context)` because those are the only two words used before any
/// call, and the mapper argument is `// unknown:` at the four sites where the
/// export drops it (0 is passed).
pub unsafe fn fn_801d9950(
    prefix: u32,
    context: usize,
    mode: u32,
    buffer: u32,
    length: u32,
) -> u32 {
    // `iVar5` and `iVar6` are the export's local flags: the first starts at 0
    // and gates the path check, the second is initialised to 1 and never
    // written, so its `== 0` arms are unreachable but kept for shape.
    let scan_only = 0u32;
    let second = 1u32;

    if fn_801da550() == 0 {
        return 0xFFFF_FF80;
    }
    if second == 0 || length & 0x3FFF == 0 {
        return 0xFFFF_FFF8;
    }

    platform::write_u8(context + 0x88, mode as u8);
    platform::write_u8(context + 0x89, 0);
    fn_801da6e0(context + 0x08, prefix as usize);
    if scan_only == 0 && fn_801da4b0(context + 0x08) != 0 {
        return 0xFFFF_FFFF;
    }

    if mode == 1 {
        let fd = platform::call2(ISFS_MODE_OP_SYNC, (context + 0x08) as u32, 1) as i32;
        if fd < 0 {
            return fn_801da570(0);
        }
        platform::write_u32(context, fd as u32);
        platform::write_u8(context + 0x89, 2);
        platform::write_u8(context + 0x8A, if second == 0 { 3 } else { 5 });
        return 0;
    }

    if (mode.wrapping_add(0xFE) & 0xFF) >= 2 {
        return 0xFFFF_FFF8;
    }

    // Scratch directory first: it is created even when it already exists, and
    // `0xFFFFFF97` (`-0x69`) is the "already there" answer.
    let created = platform::call5(ISFS_CREATE_DIR, TMP_PATH, 0, 3, 3, 3);
    if created != 0 && created != 0xFFFF_FF97 {
        return fn_801da570(0);
    }

    platform::write_u8(context + 0x89, 1);

    let mut out_a = 0u32;
    let mut out_b = 0u32;
    let mut kind = 0u32;
    let mut owner = 0u32;
    let mut group = 0u32;
    let mut other = 0u32;
    let attributes = platform::call7(
        ISFS_OP_26BF0,
        (context + 0x08) as u32,
        &mut out_a as *mut u32 as u32,
        &mut out_b as *mut u32 as u32,
        &mut kind as *mut u32 as u32,
        &mut owner as *mut u32 as u32,
        &mut group as *mut u32 as u32,
        &mut other as *mut u32 as u32,
    );
    if attributes != 0 {
        return fn_801da570(0);
    }

    let source = platform::call2(ISFS_MODE_OP_SYNC, (context + 0x08) as u32, 1) as i32;
    platform::write_u32(context + 0x04, source as u32);
    if source < 0 {
        return fn_801da570(0);
    }
    platform::write_u8(context + 0x89, 2);

    if second == 0 {
        let lock = disable_interrupts();
        let sequence = platform::read_u32(SDA_ISFS_TMP_SEQ);
        platform::write_u32(SDA_ISFS_TMP_SEQ, sequence.wrapping_add(1));
        restore_interrupts(lock);
        let mut scratch = [0u8; 0x60];
        platform::call4(
            SPRINTF,
            scratch.as_mut_ptr() as u32,
            SDA_ISFS_TMP_DIR_FORMAT as u32,
            TMP_PATH,
            sequence,
        );
        if platform::call5(
            ISFS_CREATE_DIR,
            scratch.as_ptr() as u32,
            0,
            3,
            0,
            0,
        ) != 0
        {
            return fn_801da570(0);
        }
        platform::write_u8(context + 0x89, 3);
    }

    let mut base = [0u8; 0x10];
    let base_ptr = base.as_mut_ptr() as usize;
    fn_801da2d0(base_ptr, context + 0x08);

    if second == 0 {
        platform::call5(
            SPRINTF,
            (context + 0x48) as u32,
            ISFS_TMP_NAME_FORMAT,
            TMP_PATH,
            platform::read_u32(SDA_ISFS_TMP_SEQ).wrapping_sub(1),
            base_ptr as u32,
        );
    } else {
        platform::call4(
            SPRINTF,
            (context + 0x48) as u32,
            SDA_ISFS_TMP_JOIN as u32,
            TMP_PATH,
            base_ptr as u32,
        );
    }

    let destination = platform::call5(
        ISFS_OP_273A0,
        (context + 0x48) as u32,
        kind,
        owner,
        group,
        other,
    );
    if destination != 0 {
        return fn_801da570(0);
    }

    if mode == 2 {
        let fd = platform::call2(ISFS_MODE_OP_SYNC, (context + 0x48) as u32, 2) as i32;
        platform::write_u32(context, fd as u32);
    } else {
        let fd = platform::call2(ISFS_MODE_OP_SYNC, (context + 0x48) as u32, 3) as i32;
        platform::write_u32(context, fd as u32);
    }
    let destination_fd = platform::read_u32(context) as i32;
    if destination_fd < 0 {
        return fn_801da570(0);
    }
    platform::write_u8(context + 0x89, 5);

    let mut status;
    loop {
        status = platform::call3(ISFS_OP_278A0, source as u32, buffer, length) as i32;
        if status == 0 || status < 0 {
            break;
        }
        status = platform::call2(ISFS_OP_27970, destination_fd as u32, buffer) as i32;
        if status < 0 {
            break;
        }
    }

    if status != 0 {
        return fn_801da570(status as u32);
    }
    let closed = platform::call3(ISFS_SET_MODE, destination_fd as u32, 0, 0) as i32;
    if closed == 0 {
        platform::write_u8(context + 0x8A, if second == 0 { 3 } else { 5 });
    }
    fn_801da570(0)
}

