/// Writes the two pixel-mode selector tables and clears the FIFO marker.
///
/// The pixel mode is stored at `+0x5EC` and the fog mode at `+0x5F0`/`+0x5F4`.
/// Before either is overwritten, the old value selects one or two "invalidate"
/// FIFO words so the hardware drops the stale mode. The new pixel mode then
/// selects its command word from a 35-entry table and the new fog mode from a
/// 23-entry table, eight of whose cases rewrite the packed `+0x5F4` word and
/// four of which poke a halfword inside the block that `r13 - 0x4DEC` points at.
///
/// # Original
/// - Ghidra: `FUN_801c9e20` at `0x801C9E20` (2076 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801c9e20_FUN_801c9e20.c`
///
/// # Arguments
/// - `pixel_mode`: new value stored at `+0x5EC`; 0-0x22 are mapped to command
///   words, anything else emits nothing.
/// - `fog_mode`: new value stored at `+0x5F0`; 0-8 and 0x15 map to command
///   words, 9-0x10 rewrite the packed word at `+0x5F4`, 0x11-0x14 write a
///   halfword inside the `r13 - 0x4DEC` block.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Emits up to five words to the FIFO, stores `pixel_mode`/`fog_mode` at
/// `+0x5EC`/`+0x5F0`, may rewrite `+0x5F4`, may write the halfword at `+6` of the
/// `r13 - 0x4DEC` block, and clears the halfword at `state + 2`.
///
/// # Safety
/// The GX state block, the `r13 - 0x4DEC` pointer and the FIFO must be mapped.
///
/// # Confidence
/// medium - both tables, the masks, the store order and the acknowledge are
/// literal in the export; the meaning of the two mode numbers is inferred from
/// the surrounding bring-up, and the FIFO command bytes are not decoded.
pub unsafe fn fn_801c9e20(pixel_mode: u32, fog_mode: u32) {
    let state = gx_state_base();

    // observed: the outgoing pixel mode picks the invalidate word.
    let old_pixel_mode = platform::read_u32(state + 0x5EC);
    if old_pixel_mode.wrapping_sub(0xB) < 0x10 {
        gx_fifo_write(0x2300_0000);
    } else if old_pixel_mode < 0xB {
        gx_fifo_write(0);
    } else if old_pixel_mode.wrapping_sub(0x1B) < 7 {
        gx_fifo_write(0x2400_0000);
    } else if old_pixel_mode == 0x22 {
        gx_fifo_write(0);
    }

    // observed: same step for the outgoing fog mode, but the 9-0x10 range
    // rewrites the packed word at `+0x5F4` and the 0x11-0x14 range clears a
    // halfword inside the `r13 - 0x4DEC` block.
    let old_fog_mode = platform::read_u32(state + 0x5F0);
    if old_fog_mode > 8 && old_fog_mode.wrapping_sub(9) < 8 {
        let word = platform::read_u32(state + 0x5F4) & 0xFFFF_FF0F;
        platform::write_u32(state + 0x5F4, word);
        gx_fifo_write(word);
    } else if old_fog_mode > 8 && old_fog_mode.wrapping_sub(0x11) < 4 {
        let block = platform::read_u32(SDA_BASE - 0x4DEC) as usize;
        platform::write_u16(block + 6, 0);
    } else if old_fog_mode <= 8 || old_fog_mode == 0x15 {
        gx_fifo_write(0x6700_0000);
    }

    platform::write_u32(state + 0x5EC, pixel_mode);
    match pixel_mode {
        0 => gx_fifo_write(0x273),
        1 => gx_fifo_write(0x14A),
        2 => gx_fifo_write(0x16B),
        3 => gx_fifo_write(0x84),
        4 => gx_fifo_write(0xC6),
        5 => gx_fifo_write(0x210),
        6 => gx_fifo_write(0x252),
        7 => gx_fifo_write(0x231),
        8 => gx_fifo_write(0x1AD),
        9 => gx_fifo_write(0x1CE),
        10 => gx_fifo_write(0x153),
        0xB => gx_fifo_write(0x2300_AE7F),
        0xC => gx_fifo_write(0x2300_8E7F),
        0xD => gx_fifo_write(0x2300_9E7F),
        0xE => gx_fifo_write(0x2300_1E7F),
        0xF => gx_fifo_write(0x2300_AC3F),
        0x10 => gx_fifo_write(0x2300_AC7F),
        0x11 => gx_fifo_write(0x2300_ACBF),
        0x12 => gx_fifo_write(0x2300_ACFF),
        0x13 => gx_fifo_write(0x2300_AD3F),
        0x14 => gx_fifo_write(0x2300_AD7F),
        0x15 => gx_fifo_write(0x2300_ADBF),
        0x16 => gx_fifo_write(0x2300_ADFF),
        0x17 => gx_fifo_write(0x2300_AE3F),
        0x18 => gx_fifo_write(0x2300_A27F),
        0x19 => gx_fifo_write(0x2300_A67F),
        0x1A => gx_fifo_write(0x2300_AA7F),
        0x1B => gx_fifo_write(0x2402_C0C6),
        0x1C => gx_fifo_write(0x2402_C16B),
        0x1D => gx_fifo_write(0x2402_C0E7),
        0x1E => gx_fifo_write(0x2402_C108),
        0x1F => gx_fifo_write(0x2402_C129),
        0x20 => gx_fifo_write(0x2402_C14A),
        0x21 => gx_fifo_write(0x2402_C1AD),
        0x22 => gx_fifo_write(0x21),
        _ => {}
    }

    platform::write_u32(state + 0x5F0, fog_mode);
    match fog_mode {
        0 => gx_fifo_write(0x6700_0042),
        1 => gx_fifo_write(0x6700_0084),
        2 => gx_fifo_write(0x6700_0063),
        3 => gx_fifo_write(0x6700_0129),
        4 => gx_fifo_write(0x6700_014B),
        5 => gx_fifo_write(0x6700_018D),
        6 => gx_fifo_write(0x6700_01CF),
        7 => gx_fifo_write(0x6700_0211),
        8 => gx_fifo_write(0x6700_0252),
        9..=0x10 => {
            // observed: bits 4-7 of `+0x5F4` select the fog table entry; every
            // other field is preserved.
            let field = match fog_mode {
                9 => 0x20,
                10 => 0x30,
                0xB => 0x40,
                0xC => 0x50,
                0xD => 0x60,
                0xE => 0x70,
                0xF => 0x90,
                _ => 0x80,
            };
            let word = (platform::read_u32(state + 0x5F4) & 0xFFFF_FF0F) | field;
            platform::write_u32(state + 0x5F4, word);
            gx_fifo_write(word);
        }
        0x11..=0x14 => {
            let block = platform::read_u32(SDA_BASE - 0x4DEC) as usize;
            platform::write_u16(block + 6, (fog_mode - 0x0F) as u16);
        }
        0x15 => gx_fifo_write(0x6700_0021),
        _ => {}
    }

    gx_state_ack(state);
}

/// Closes one pixel block: emits the `0x98` header, pads it and then emits the
/// two trailing parameters.
///
/// `0x801C56C0` is the unconditional half of the pair; this variant first
/// flushes a pending dirty word through [`fn_801c52f0`] when `+0x5FC` is
/// non-zero, only emits the header and the padding while the word at `state + 0`
/// is zero, and closes with the caller's two values.
///
/// # Original
/// - Ghidra: `FUN_801c5570` at `0x801C5570` (332 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801c5570_FUN_801c5570.c`
///
/// # Arguments
/// - `_unused`: first argument; saved to `r28` and never read, exactly as the
///   export shows.
/// - `low_byte`: low eight bits are emitted as the first byte after the padding.
/// - `half`: emitted as the following halfword.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// May call `0x801C52F0`, emits the `0x98` command byte plus the width halfword
/// and `round_up(width*height, 4)` zero bytes to `0xCC008000`, sets the halfword
/// at `state + 2` to `1`, then emits the byte and the halfword.
///
/// # Safety
/// The GX state block and the FIFO must be mapped.
///
/// # Confidence
/// medium - every store, mask and loop count is literal in the export; the last
/// two emissions are `stb`/`sth` pairs that the export merges into one word
/// store (Wave 80 left the body out for that reason), and the byte stream at
/// `work/dol/main.elf` resolves the merge.
pub unsafe fn fn_801c5570(_unused: u32, low_byte: u32, half: u16) {
    let state = gx_state_base();
    if platform::read_u32(state + 0x5FC) != 0 {
        fn_801c52f0();
    }
    if platform::read_u32(state) == 0 {
        let width = platform::read_u16(state + 4) as u32;
        let height = platform::read_u16(state + 6) as u32;
        // observed: `stb 0x98` then `sth width` to `0xCC008000`.
        platform::write_u8(GX_FIFO, 0x98);
        platform::write_u16(GX_FIFO, width as u16);
        gx_fifo_zero_fill(width.wrapping_mul(height));
        platform::write_u16(state + 2, 1);
    }
    // observed: `stb low_byte` then `sth half`; the export prints these as a
    // single word store whose low half re-reads the write-only port.
    platform::write_u8(GX_FIFO, low_byte as u8);
    platform::write_u16(GX_FIFO, half);
}

/// Emits the `0x98` block header, its pixel padding and the state acknowledge.
///
/// This is the unconditional twin of [`fn_801c5570`]: it never consults
/// `state + 0` and never takes trailing parameters, so it always emits the
/// `0x98` byte, the width halfword and `round_up(width*height, 4)` zero bytes.
///
/// # Original
/// - Ghidra: `FUN_801c56c0` at `0x801C56C0` (216 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801c56c0_FUN_801c56c0.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Emits `0x98`, `width` and the zero padding to `0xCC008000` and sets the
/// halfword at `state + 2` to `1`.
///
/// # Safety
/// The GX state block and the FIFO must be mapped.
///
/// # Confidence
/// medium - all stores, masks and loop counts are literal in the export; the
/// export types the padding stores as halfwords while the listing shows `stw`
/// words, which is the `round_up(pixels, 4)` byte budget.
pub unsafe fn fn_801c56c0() {
    let state = gx_state_base();
    let width = platform::read_u16(state + 4) as u32;
    let height = platform::read_u16(state + 6) as u32;
    // observed: `stb 0x98` then `sth width` to `0xCC008000`.
    platform::write_u8(GX_FIFO, 0x98);
    platform::write_u16(GX_FIFO, width as u16);
    gx_fifo_zero_fill(width.wrapping_mul(height));
    platform::write_u16(state + 2, 1);
}

/// Programs the whole default GX state for one display-mode record.
///
/// The routine reads the display-mode index from `0x801BE010`, selects one of
/// four records in the `0x803410A8`-`0x80341198` band, and then walks the state
/// in the same order the driver does at start-up: texcoord generators, indirect
/// and TEV stages, the 3x4 identity block, the texture objects, the four
/// channels, the fog selector and finally the VI/`0x23`/`0x16` mode pair.
///
/// # Original
/// - Ghidra: `FUN_801c22c0` at `0x801C22C0` (2240 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801c22c0_FUN_801c22c0.c`
///
/// # Arguments
/// None. The display-mode index and the small-data constants are read from
/// memory, exactly as the export shows.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Calls about ninety routines by absolute address, resets the dirty flags and
/// the selector words at `+0x5EC`/`+0x5F0` through [`fn_801c9e20`], and emits
/// to the FIFO through the callees.
///
/// # Safety
/// The GX state block, the display-mode records, the four tables in the
/// `0x80340C40`-`0x80340D30` band and the FIFO must all be mapped.
///
/// # Confidence
/// medium - the call order and every argument are literal in the export; the
/// record field roles and the small-data constants are `// inferred:` and their
/// values are not established here.
pub unsafe fn fn_801c22c0() {
    let state = gx_state_base();
    // observed: `0x4EF0`/`0x4EE4` are read as single-precision; `0x4EEC`/`0x4EE8`
    // are copied as raw words into the FIFO emitters.
    let off_diagonal = platform::read_f32(sda2(SDA_GX_MATRIX_OFF));
    let diagonal = platform::read_f32(sda2(SDA_GX_MATRIX_DIAG));
    let fog_third = platform::read_f32(sda2(SDA_GX_FOG_THIRD));
    let color = platform::read_u32(sda2(SDA_GX_DEFAULT_COLOR));
    let image = platform::read_u32(sda2(SDA_GX_DEFAULT_IMAGE));

    let mode = match call0_ret(GX_GET_DISPLAY_MODE) {
        1 => GX_MODE_RECORD_1,
        2 => GX_MODE_RECORD_HI,
        5 => GX_MODE_RECORD_5,
        _ => GX_MODE_RECORD_0,
    };

    fn_801c5ec0(color, 0x00FF_FFFF);

    // observed: texcoord 0-7 get a type-1 generator whose format is index + 4.
    for index in 0..8u32 {
        fn_801c47d0(index, 1, index + 4, 0x3C, 0, 0x7D);
    }
    fn_801c4a20(1);
    fn_801c4070();
    fn_801c47c0();
    // observed: texcoord records 9-0x18 are cleared with the state block as the
    // second argument.
    for index in 9..0x19u32 {
        fn_801c4780(index, state as u32, 0);
    }
    for index in 0..8u32 {
        fn_801c4250(index, GX_TEXCOORD_GEN_TABLE);
    }

    fn_801c57a0(6, 0);
    fn_801c57e0(6, 0);
    for index in 0..8i32 {
        fn_801c5820(index, 0, 0);
    }

    // observed: a twelve-word 3x4 block with `diagonal` on the diagonal and
    // `off_diagonal` everywhere else; the same block is loaded three times.
    let mut matrix = [off_diagonal.to_bits(); 12];
    matrix[0] = diagonal.to_bits();
    matrix[5] = diagonal.to_bits();
    matrix[10] = diagonal.to_bits();
    let matrix_addr = matrix.as_ptr() as usize;
    fn_801c9940(matrix_addr, 0);
    fn_801c99c0(matrix_addr);
    fn_801c9a60(0);
    platform::call3(0x801C_9A80, matrix_addr as u32, 0x3C, 0);
    platform::call3(0x801C_9A80, matrix_addr as u32, 0x7D, 0);

    let width = platform::read_u16(mode + 4);
    let height = platform::read_u16(mode + 6);
    let second_width = platform::read_u16(mode + 8);
    // observed: `CONCAT44(0x43300000, half) - 2^52` is the compiler's
    // integer-to-double conversion, so the two expressions are the halfwords as
    // floats.
    fn_801c9c10(
        off_diagonal as f64,
        off_diagonal as f64,
        width as f32 as f64,
        second_width as f32 as f64,
        off_diagonal as f64,
        diagonal as f64,
    );

    fn_801c98b0(GX_STATE_BLOCK_0D30);
    fn_801c58f0();
    fn_801c58b0(0);
    fn_801c5860(2);
    fn_801c9d60(0);
    fn_801c9c60(0, 0, width as i32, height as i32);
    fn_801c9d20(0, 0);
    fn_801c6ac0(0);

    // observed: two texture objects (selectors 4 and 5) with the same 7-argument
    // format word and the shared `0x4EE8` image word.
    platform::call7(0x801C_6AF0, 4, 0, 0, 1, 0, 0, 2);
    let mut texture_selector = 0u32;
    fn_801c6900(4, &mut texture_selector as *mut u32 as usize);
    let mut texture_image = image;
    fn_801c69e0(4, &mut texture_image as *mut u32 as usize);
    platform::call7(0x801C_6AF0, 5, 0, 0, 1, 0, 0, 2);
    let mut texture_selector_hi = 0u32;
    fn_801c6900(5, &mut texture_selector_hi as *mut u32 as usize);
    let mut texture_image_hi = image;
    fn_801c69e0(5, &mut texture_image_hi as *mut u32 as usize);

    fn_801c76c0();
    fn_801c7710(0x801C_19F0);
    fn_801c7730(0x801C_1AE0);
    let mut object = [0u32; 8];
    fn_801c6d90(
        object.as_mut_ptr() as usize,
        GX_TEXTURE_FORMAT_TABLE as u32,
        4,
        4,
        3,
        0,
        0,
        0,
    );
    for index in 0..8u32 {
        fn_801c74c0(object.as_mut_ptr() as usize, index);
    }

    // observed: eight generated texcoords, then eight constant 0xFF entries.
    for index in 0..8u32 {
        fn_801c8790(index, index, index, 4);
    }
    for index in 8..0x10u32 {
        fn_801c8790(index, 0xFF, 0xFF, 0xFF);
    }
    fn_801c88f0(1);
    fn_801c8250(0, 3);
    fn_801c86c0(7, 0, 0, 7, 0);
    platform::call3(0x801C_8700, 0, 0x11, 0);

    for index in 0..0x10u32 {
        fn_801c8560(index, 6);
        fn_801c85b0(index, 0);
        fn_801c8600(index, 0, 0);
    }
    fn_801c8640(0, 0, 1, 2, 3);
    fn_801c8640(1, 0, 0, 0, 3);
    fn_801c8640(2, 1, 1, 1, 3);
    fn_801c8640(3, 2, 2, 2, 3);
    for index in 0..0x10u32 {
        fn_801c8130(index);
    }
    fn_801c8110(0);
    for select in 0..4u32 {
        fn_801c7f40(select, 0, 0);
    }

    // observed: the fog setup takes four doubles and a pointer to the six-word
    // result block.
    let mut fog_state = 0u32;
    call_f64x4(
        0x801C_8920,
        off_diagonal as f64,
        diagonal as f64,
        fog_third as f64,
        diagonal as f64,
        0,
        &mut fog_state as *mut u32 as u32,
    );

    platform::call3(0x801C_8CB0, 0, 0, 0);
    fn_801c8dc0(0, 4, 5, 0);
    fn_801c8e10(1);
    fn_801c8e40(1);
    fn_801c8e70(1, 3, 1);
    fn_801c8eb0(1);
    fn_801c8f90(1);
    fn_801c8fc0(0, 0);
    fn_801c8ee0(0, 0);
    fn_801c8ff0(1, 1);
    fn_801c9030(
        platform::read_u8(mode + 0x18) as u32,
        (platform::read_u16(mode + 0x10) as u32 == (platform::read_u16(mode + 8) as u32) << 1) as u32,
    );
    fn_801c5920(0, 0, width as i32, height as i32);
    platform::call2(0x801C_59A0, width as u32, height as u32);
    fn_801c5df0(second_width as f32 / height as f32);
    fn_801c5b00(3);
    // observed: the record supplies the sample table at +0x1A (24 bytes) and
    // the vertical filter at +0x32 (7 bytes, behind the +0x19 enable byte).
    fn_801c5f40(
        platform::read_u8(mode + 0x19) as u32,
        mode + 0x1A,
        1,
        mode + 0x32,
    );
    fn_801c6130(0);
    fn_801c5ae0(0);
    fn_801c63f0();
    fn_801c5050(1);
    fn_801c4fd0(1);
    fn_801c5090(0);
    fn_801c4ff0(0, 0, 1, 0xF);
    fn_801c4fa0(7, 0);
    fn_801c4fb0(1);
    fn_801c5070(0, 0);
    fn_801c50b0(1, 7, 1);
    fn_801c9e20(0x23, 0x16);
    fn_801ca640();
}

// ---------------------------------------------------------------------------
// Wave 106: the last nine addresses of the 0x801C0000 page
// ---------------------------------------------------------------------------
//
// Wave 105 skipped all nine remaining addresses because their exports looked
// inconsistent with `functions.tsv`. Re-reading them against the raw
// instruction stream (`work/dol/main.elf`) shows that eight are ordinary GX
// routines: the exports were truncated (the two wrappers, the copy-filter and
// BP-table writers, the fog setter) or expanded by the paired-single prologue,
// not wrong. Those eight are translated below. `0x801C90A0` is still out; the
// exact reason is in `docs/COVERAGE_WAVE106_DVD.md`.
//
// **GQR0 note.** As in the Wave 90/95/100/105 sections, the paired-single
// quantised arms are not reproduced. The bodies below are the plain `f32` arm
// and each `# Confidence` block says so.

/// Emits one BP register word: the `0x61` mask byte, then the 32-bit word whose
/// top byte is the register number.
///
/// # Safety
/// `0xCC008000` must be the mapped GX FIFO.
#[inline]
unsafe fn gx_bp_write(word: u32) {
    platform::write_u8(GX_FIFO, 0x61);
    gx_fifo_write(word);
}

/// Calls the SDK's double-precision sine (`0x802E84C4`).
///
/// The two entry points take a `double` in `f1` and return one in `f1`; the
/// small-argument arm calls the polynomial kernel `0x802E7904`, which is the
/// sine series (`x + x^3 * ...`).
///
/// # Safety
/// `0x802E84C4` must be the entry point of an `f64(f64)` routine.
#[inline]
unsafe fn fp_sin_f64(value: f64) -> f64 {
    let f: extern "C" fn(f64) -> f64 = core::mem::transmute(FP_SIN_F32);
    f(value)
}

/// Calls the SDK's double-precision cosine (`0x802E7FBC`).
///
/// Its small-argument arm calls the polynomial kernel `0x802E613C`, which is the
/// cosine series (`1 - x^2 * ...`), so the pair is sine/cosine and not the
/// reverse.
///
/// # Safety
/// `0x802E7FBC` must be the entry point of an `f64(f64)` routine.
#[inline]
unsafe fn fp_cos_f64(value: f64) -> f64 {
    let f: extern "C" fn(f64) -> f64 = core::mem::transmute(FP_COS_F32);
    f(value)
}

/// Multiplies one 3x4 matrix into every matrix of an array.
///
/// This is the array form of [`fn_801c0540`]: the left operand `m` is fixed and
/// each 48-byte element of `src` is concatenated into the matching element of
/// `dst`. The caller at `0x8024FEF0` uses it exactly that way, and only for
/// `count > 1` (a single matrix goes through `0x801C0540`).
///
/// # Original
/// - Ghidra: `FUN_801c0610` at `0x801C0610` (392 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801c0610_FUN_801c0610.c`
///
/// # Arguments
/// - `m`: shared left matrix, twelve floats in three rows of four.
/// - `src`: array of `count` 3x4 matrices, 48 bytes apart.
/// - `dst`: array of `count` destination matrices, 48 bytes apart.
/// - `count`: number of matrices; the body is a no-op for `count == 0`.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Writes `48 * count` bytes at `dst`.
///
/// # Safety
/// `m` must address 48 readable bytes, `src` `48 * count` readable bytes and
/// `dst` `48 * count` writable bytes. The ranges must not overlap.
///
/// # Confidence
/// medium - the 0x30 stride, the three-term dot products and the two
/// `0x804295A0`/`0x804295A4` column constants are literal in the export and
/// identical to `0x801C0540`; the paired-single quantised arms are not
/// reproduced (see the GQR0 note above).
pub unsafe fn fn_801c0610(m: usize, src: usize, dst: usize, count: u32) {
    // observed: `r13 - 0x60E0` = 0x804295A0, the same pair `0x801C0540` reads.
    let c0 = platform::read_f32(MTX_CONCAT_C0);
    let c1 = platform::read_f32(MTX_CONCAT_C1);
    let mut index = 0u32;
    while index < count {
        let b = src + index as usize * 0x30;
        let out = dst + index as usize * 0x30;
        let mut row = 0usize;
        while row < 3 {
            let a = m + row * 0x10;
            let a0 = platform::read_f32(a);
            let a1 = platform::read_f32(a + 0x04);
            let a2 = platform::read_f32(a + 0x08);
            let a3 = platform::read_f32(a + 0x0C);
            let d = out + row * 0x10;
            // observed: products run backwards (column 2 first), as in
            // [`fn_801c0540`]; the fourth column adds `1 * a3`.
            platform::write_f32(
                d,
                a2 * platform::read_f32(b + 0x20)
                    + a1 * platform::read_f32(b + 0x10)
                    + a0 * platform::read_f32(b),
            );
            platform::write_f32(
                d + 0x04,
                a2 * platform::read_f32(b + 0x24)
                    + a1 * platform::read_f32(b + 0x14)
                    + a0 * platform::read_f32(b + 0x04),
            );
            platform::write_f32(
                d + 0x08,
                c0 * a3
                    + a2 * platform::read_f32(b + 0x28)
                    + a1 * platform::read_f32(b + 0x18)
                    + a0 * platform::read_f32(b + 0x08),
            );
            platform::write_f32(
                d + 0x0C,
                c1 * a3
                    + a2 * platform::read_f32(b + 0x2C)
                    + a1 * platform::read_f32(b + 0x1C)
                    + a0 * platform::read_f32(b + 0x0C),
            );
            row += 1;
        }
        index += 1;
    }
}

/// Builds a rotation matrix about a named axis from an `f64` angle.
///
/// The body is the thin wrapper around [`fn_801c09f0`]: it converts the angle to
/// `f32` sine/cosine and forwards them with the destination and the axis
/// character.
///
/// # Original
/// - Ghidra: `FUN_801c0970` at `0x801C0970` (124 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801c0970_FUN_801c0970.c`
///
/// # Arguments
/// - `angle`: rotation angle in radians (the incoming `f1`).
/// - `out`: destination, twelve floats in three rows of four.
/// - `axis`: axis character, `'X'`/`'Y'`/`'Z'` or their lowercase forms.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Calls `0x802E84C4` (sine) and `0x802E7FBC` (cosine), then writes 48 bytes at
/// `out` through [`fn_801c09f0`].
///
/// # Safety
/// `out` must address 48 writable bytes.
///
/// # Confidence
/// high - the two calls, the `frsp` pair and the argument shuffle (`r3`/`r4`
/// saved to `r30`/`r31`) are literal; the sine/cosine identity is proven by the
/// kernels those two entries call.
pub unsafe fn fn_801c0970(angle: f64, out: usize, axis: u32) {
    let sine = fp_sin_f64(angle) as f32;
    let cosine = fp_cos_f64(angle) as f32;
    fn_801c09f0(sine, cosine, out, axis);
}

/// Builds the `X`, `Y` or `Z` rotation matrix selected by an axis character.
///
/// The selector is `axis | 0x20`, compared with `0x78`, `0x79` and `0x7A`
/// (`'x'`, `'y'`, `'z'`). Each arm writes a 3x4 matrix; the fourth word of each
/// row is the SDA2 zero and the diagonal entry is either the SDA2 one (the
/// rotation axis itself) or the cosine.
///
/// # Original
/// - Ghidra: `FUN_801c09f0` at `0x801C09F0` (176 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801c09f0_FUN_801c09f0.c`
///
/// # Arguments
/// - `sine`, `cosine`: the sine and cosine of the angle, already narrowed to
///   `f32` by the caller.
/// - `out`: destination, twelve floats in three rows of four.
/// - `axis`: axis character; any other value returns without writing.
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Writes 48 bytes at `out` for `x`, `y` and `z`; returns untouched otherwise.
///
/// # Safety
/// `out` must address 48 writable bytes.
///
/// # Confidence
/// high - the three arms, the `ps_neg` of the sine, the `ps_merge00` pairs and
/// every destination offset are literal in the listing; the constant slots are
/// the same `r2 - 0x4F50` one and `r2 - 0x4F4C` zero that `0x801C04D0` uses.
/// The quantised store arms are not reproduced (GQR0 note above).
pub unsafe fn fn_801c09f0(sine: f32, cosine: f32, out: usize, axis: u32) {
    let one = sda_f32(MTX_ONE);
    let zero = sda_f32(MTX_ZERO);
    // observed: `ori r0,r4,0x20` folds 'X'/'x' and friends together.
    match axis | 0x20 {
        0x78 => {
            // [1 0 0 0; 0 c -s 0; 0 s c 0]
            platform::write_f32(out + 0x00, one);
            platform::write_f32(out + 0x04, zero);
            platform::write_f32(out + 0x08, zero);
            platform::write_f32(out + 0x0C, zero);
            platform::write_f32(out + 0x10, zero);
            platform::write_f32(out + 0x14, cosine);
            platform::write_f32(out + 0x18, -sine);
            platform::write_f32(out + 0x1C, zero);
            platform::write_f32(out + 0x20, zero);
            platform::write_f32(out + 0x24, sine);
            platform::write_f32(out + 0x28, cosine);
            platform::write_f32(out + 0x2C, zero);
        }
        0x79 => {
            // [c 0 s 0; 0 1 0 0; -s 0 c 0]
            platform::write_f32(out + 0x00, cosine);
            platform::write_f32(out + 0x04, zero);
            platform::write_f32(out + 0x08, sine);
            platform::write_f32(out + 0x0C, zero);
            platform::write_f32(out + 0x10, zero);
            platform::write_f32(out + 0x14, one);
            platform::write_f32(out + 0x18, zero);
            platform::write_f32(out + 0x1C, zero);
            platform::write_f32(out + 0x20, -sine);
            platform::write_f32(out + 0x24, zero);
            platform::write_f32(out + 0x28, cosine);
            platform::write_f32(out + 0x2C, zero);
        }
        0x7A => {
            // [c -s 0 0; s c 0 0; 0 0 1 0]
            platform::write_f32(out + 0x00, cosine);
            platform::write_f32(out + 0x04, -sine);
            platform::write_f32(out + 0x08, zero);
            platform::write_f32(out + 0x0C, zero);
            platform::write_f32(out + 0x10, sine);
            platform::write_f32(out + 0x14, cosine);
            platform::write_f32(out + 0x18, zero);
            platform::write_f32(out + 0x1C, zero);
            platform::write_f32(out + 0x20, zero);
            platform::write_f32(out + 0x24, zero);
            platform::write_f32(out + 0x28, one);
            platform::write_f32(out + 0x2C, zero);
        }
        _ => {}
    }
}

